function removeUserPhoto(userId){
  if(!user||(user.profile!=='master'&&user.profile!=='admin'&&user.profile!=='gestor_ti')){
    toast('Sem permissão para alterar fotos','e');
    return;
  }
  const d=getDB();
  const u=d.users.find(x=>x.id===userId);
  if(!u||!u.photo){toast('Usuário não possui foto para remover','i');return}
  showConfirm('Remover Foto',`Deseja remover a foto de <b>${s(u.nome)}</b>?`,function(){
    const db=getDB();
    const usr=db.users.find(x=>x.id===userId);
    if(usr){
      usr.photo='';
      usr.photoUpdated=Date.now();
      db.users=db.users.map(x=>x.id===userId?usr:x);
      db._lastUpdate=Date.now();
      db._dataCount=countData(db);
      setDB(db);
      if(userId===user.id){user.photo='';localStorage.setItem('gv_user',JSON.stringify({...user,_loginTime:user._loginTime||Date.now()}))}
      pushToFirebase();
      addLog('update',`Foto removida do usuário ${usr.nome}`);
      toast('Foto removida!','s');
      renderAll();
    }
  });
}

