function bdg(v){const m={'Em uso':'s','Estoque':'i','Manutenção':'w','Baixado':'m','Crítico':'d','Baixo':'w','OK':'s','Aberto':'d','Em atendimento':'w','Em_analise':'i','Em Análise':'i','Atendido':'s','Em Separação':'w','Em_Separacao':'w','Separado':'s','Nova':'i','Respondida':'s','Arquivada':'m','Concluído':'s','Concluido':'s','Finalizado':'s','Aprovado':'s','Pendente':'w','Bloqueado':'d','Ativo':'s','Desligado':'d','Urgente':'d','Alta':'d','Média':'w','Baixa':'s','Master':'p','Administrador TI':'p','Gestor TI':'i','Técnico TI':'w','Gestor':'i','Funcionário':'s','Revogado':'d'};return`<span class="badge badge-${m[v]||'m'}">${s(v)}</span>`}

function genSN(){const c=['DL','LN','HP','SM','LG'];return`SN-${new Date().getFullYear()}-${c[Math.floor(Math.random()*c.length)]}-${Math.floor(Math.random()*90000)+10000}`}
function genToken(len=32){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';let t='';for(let i=0;i<len;i++)t+=chars.charAt(Math.floor(Math.random()*chars.length));return t}

function checkBirthdays(d){
  if(!user)return;
  const today=new Date();
  const day=today.getDate();
  const month=today.getMonth()+1;
  const bdayKey='birthday_sent_'+month+'_'+today.getFullYear();
  if(localStorage.getItem(bdayKey))return;
  const birthdays=(d.employees||[]).filter(e=>{
    if(!e.nasc)return false;
    try{
      const parts=e.nasc.split('/');
      if(parts.length===3){
        const bMonth=parseInt(parts[1]);
        const bDay=parseInt(parts[0]);
        return bMonth===month&&bDay===day;
      }
      if(parts.length===1&&e.nasc.includes('-')){
        const d2=new Date(e.nasc+'T00:00:00');
        return(d2.getMonth()+1===month&&d2.getDate()===day);
      }
    }catch(ex){}
    return false;
  });
  if(birthdays.length>0){
    const names=birthdays.map(e=>e.nome);
    localStorage.setItem(bdayKey,'1');
    showConfirm('🎂 Aniversariantes de '+today.toLocaleDateString('pt-BR'),'<div style="text-align:center;padding:12px"><div style="font-size:36px;margin-bottom:12px">🎉🎂🥳</div><div style="font-size:14px;font-weight:700;margin-bottom:16px">Feliz Aniversário!</div>'+names.map(n=>'<div style="padding:8px 16px;background:var(--acg);border-radius:8px;margin:6px 0;font-weight:600;color:var(--ac)">🎂 '+s(n)+'</div>').join('')+'</div>',()=>{addLog('birthday',`Aniversariantes do dia: ${names.join(', ')}`)});
    toast('🎂 '+names.length+' aniversariante(s) hoje!','s');
  }
}

