/**
 * Remove os registros de DEMONSTRACAO que ficaram gravados no banco.
 * A limpeza roda NO SERVIDOR (a senha master e conferida la) e o cache
 * local e alinhado depois. Dado real nao e tocado: o servidor reconhece
 * a demonstracao pela marca do registro (ficha, codigo SAC2024xxx, faixa
 * de OS da base de Qualidade).
 */
async function limparDadosDemo(){
  try{
    const senha=prompt('🧹 Remover dados de DEMONSTRACAO\n\nSerao removidos do banco os registros de demonstracao (Open Issues, Indicadores e base da Qualidade). O dado real NAO e tocado.\n\nDigite a senha master para confirmar:');
    if(!senha){toast('Operação cancelada','i');return}
    const r=await apiCall('/api/admin?op=limpar-demo',{method:'POST',body:{senha:senha}});
    if(!(r&&r.ok)){toast('Não foi possível remover os dados de demonstração','e');return}
    const d=getDB();
    d.indSac=[];d.indInsp=[];delete d.indDemo;
    d.openIssues=(d.openIssues||[]).filter(x=>!demoMarcaOpen(x));
    d.QualidadeData=(d.QualidadeData||[]).filter(x=>!demoMarcaQual(x));
    setDB(d);
    try{pushToFirebase()}catch(e){}
    try{indAuditLog('dados_limpos','Dados de demonstracao removidos: '+(r.total||0)+' registro(s)')}catch(e){}
    renderAll();
    toast((r.total||0)+' registro(s) de demonstração removidos.','s');
  }catch(err){
    toast((err&&err.message)||'Não foi possível remover os dados de demonstração','e');
  }
}
function demoMarcaOpen(r){return !!(r&&String(r.ficha||'').match(/^F-\d{3}$/))}
function demoMarcaQual(r){const os=Number(r&&r.os);return isFinite(os)&&os>=9500&&os<=9579}

function renderInv(d){renderInvTable(d.inventory)}
function renderInvTable(items){const showIMEI=(user&&['master','admin'].includes(user.profile));const del=canDelete();document.getElementById('invCheckTh')?.style.setProperty('display',del?'':'none');document.getElementById('inventoryTable').innerHTML=items.map(x=>`<tr>${del?`<td><input type="checkbox" class="inv-check" data-id="${x.id}" onchange="updateInvSelected()"></td>`:''}<td class="tp" style="font-family:'JetBrains Mono',monospace;font-size:12px">${s(x.pat)}</td><td style="font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--ac)">${s(x.sn)}</td><td>${s(x.eq)}</td><td>${s(x.mm)}</td><td>${s(x.dept)}</td><td>${s(x.resp||'-')}</td><td>${bdg(x.status)}</td><td style="font-family:'JetBrains Mono',monospace;font-weight:600">${s(x.val||'-')}</td>${showIMEI?`<td style="font-size:11px">${x.imei1?`<div style="font-family:'JetBrains Mono',monospace;color:var(--w)">IMEI: ${s(x.imei1)}</div>${x.imei2?`<div style="font-family:'JetBrains Mono',monospace;color:var(--t3)">IMEI2: ${s(x.imei2)}</div>`:''}${x.chip?`<div style="color:var(--t3)">${s(x.chip)}</div>`:''}`:'-'}</td>`:''}<td><button class="btn btn-g btn-sm" onclick="editInv(${x.id})" style="padding:4px 8px;font-size:11px">✏️</button> <button class="btn btn-g btn-sm" onclick="delInv(${x.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button></td></tr>`).join('')}

