function updateInvSelected(){const sel=document.querySelectorAll('.inv-check:checked');const count=sel.length;const el=document.getElementById('invSelectedCount');const btn=document.getElementById('invBulkDelBtn');if(count>0){el.style.display='inline';el.textContent=count+' selecionado(s)';btn.style.display='inline-flex'}else{el.style.display='none';btn.style.display='none'}}
function bulkDeleteInv(){const sel=document.querySelectorAll('.inv-check:checked');if(!sel.length){toast('Nenhum item selecionado','e');return}const ids=Array.from(sel).map(c=>parseInt(c.dataset.id));const d=getDB();const items=d.inventory.filter(x=>ids.includes(x.id));const pats=items.map(x=>x.pat);showConfirm('Excluir '+ids.length+' itens',`Excluir: ${pats.map(p=>s(p)).join(', ')}?`,()=>{d.inventory=d.inventory.filter(x=>!ids.includes(x.id));ids.forEach(id=>addDeletedId(d,id,'inventory'));items.forEach(x=>addLog('delete',`Patrimônio excluído em lote: ${x.pat}`));setDB(d);pushToFirebase();renderAll();toast(ids.length+' patrimônios excluídos!','e')})}

function renderStk(d){const stkSec=document.getElementById('sec-Estoque');if(stkSec)stkSec.style.display='none';document.getElementById('stockTable').innerHTML=d.stock.map(x=>`<tr><td style="width:30px"><input type="checkbox" class="stk-check" data-id="${x.id}" onchange="updateStkSelected()"></td><td class="tp">${s(x.icon)} ${s(x.name)}</td><td>${s(x.cat)}</td><td style="font-family:'JetBrains Mono',monospace">${x.ent}</td><td style="font-family:'JetBrains Mono',monospace">${x.sai}</td><td style="font-family:'JetBrains Mono',monospace;font-weight:700">${x.saldo}</td><td>${bdg(x.status)}</td><td ${canDelete()?'':'style="display:none"'}><button class="btn btn-g btn-sm" onclick="editStk(${x.id})" style="padding:4px 8px;font-size:11px">✏️</button> <button class="btn btn-g btn-sm" onclick="delStk(${x.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button></td></tr>`).join('')}

function toggleAllStk(checked){document.querySelectorAll('.stk-check').forEach(c=>c.checked=checked);updateStkSelected()}

function updateStkSelected(){const sel=document.querySelectorAll('.stk-check:checked');const count=sel.length;const el=document.getElementById('stkSelectedCount');const btn=document.getElementById('stkBulkDelBtn');const th=document.getElementById('stkCheckTh');if(count>0){el.style.display='inline';el.textContent=count+' selecionado(s)';btn.style.display='inline-flex';th.style.display=''}else{el.style.display='none';btn.style.display='none'}}

function bulkDeleteStk(){const sel=document.querySelectorAll('.stk-check:checked');if(!sel.length){toast('Nenhum item selecionado','e');return}const ids=Array.from(sel).map(c=>parseInt(c.dataset.id));const d=getDB();const names=d.stock.filter(x=>ids.includes(x.id)).map(x=>x.name);showConfirm('Excluir '+ids.length+' itens',`Excluir: ${names.map(n=>s(n)).join(', ')}?`,()=>{d.stock=d.stock.filter(x=>!ids.includes(x.id));ids.forEach(id=>addDeletedId(d,id,'stock'));ids.forEach(id=>addLog('delete',`Item Estoque excluído em lote: ${id}`));setDB(d);pushToFirebase();renderAll();toast(ids.length+' itens excluídos!','e')})}

function rateTkt(id){const d=getDB();const t=d.tickets.find(x=>x.id===id);if(!t)return;const val=prompt('Avalie de 1 a 10:',t.rating||'10');if(!val)return;const n=parseInt(val);if(isNaN(n)||n<1||n>10){toast('Valor de 1 a 10','e');return}t.rating=n;t.ratingUser=user?.nome||'Sistema';t.ratingDate=new Date().toLocaleString('pt-BR');setDB(d);addLog('rate',`Chamado #${id} avaliado com ${n}/10 por ${t.ratingUser}`);renderAll();toast('Avaliação registrada!','s')}

function tktMilestone(v){if(!v)return null;const p=String(v).split(' ');return p[0]?{d:p[0],h:(p[1]||'').slice(0,5)}:{d:String(v),h:''}}
function tktTimeline(x){
  const steps=[
    {k:'criadoEm',por:x.criadoPor,label:'Criado',color:'var(--ac)'},
    {k:'aceitoEm',por:x.aceitoPor,label:'Aceito',color:'#8b5cf6'},
    {k:'atendidoEm',por:x.atendidoPor,label:'Atendido',color:'var(--w)'},
    {k:'finalizadoEm',por:x.finalizadoPor,label:'Finalizado',color:'var(--s)'}
  ];
  let html='<div style="display:flex;align-items:center;gap:0;flex-wrap:wrap">';
  steps.forEach((st,i)=>{
    const m=tktMilestone(x[st.k]);
    html+='<div style="display:flex;align-items:center">';
    html+='<div title="'+st.label+(m?': '+x[st.k]:' - pendente')+'" style="width:9px;height:9px;border-radius:50%;background:'+(m?st.color:'var(--bd)')+';flex:none;'+(m?'box-shadow:0 0 0 3px rgba(255,255,255,.04)':'')+'"></div>';
    if(m)html+='<div style="font-size:9px;color:var(--t3);margin-left:3px;line-height:1.15">'+m.d.slice(6,10)+'/'+m.d.slice(3,5)+(m.h?'<br>'+m.h:'')+'</div>';
    if(i<steps.length-1)html+='<div style="width:14px;height:2px;background:var(--bd);margin:0 3px;opacity:'+(x[steps[i+1].k]?'.9':'.35')+'"></div>';
    html+='</div>';
  });
  html+='</div>';
  return html;
}
function tktTimelineFull(x){
  const steps=[
    {k:'criadoEm',por:x.criadoPor,label:'Criado',icon:'🆕',color:'var(--ac)'},
    {k:'aceitoEm',por:x.aceitoPor,label:'Aceito pelo suporte',icon:'🔍',color:'#8b5cf6'},
    {k:'atendidoEm',por:x.atendidoPor,label:'Atendido',icon:'✅',color:'var(--w)'},
    {k:'finalizadoEm',por:x.finalizadoPor,label:'Finalizado',icon:'📦',color:'var(--s)'}
  ];
  const last=steps.map(s=>s.k).reduce((acc,k,i)=>x[k]?i:acc,-1);
  let html='<div style="background:var(--bg);border:1px solid var(--bd);border-radius:8px;padding:12px"><div style="font-weight:700;font-size:12px;color:var(--t3);margin-bottom:10px">⏱️ Controle de Tempos</div>';
  steps.forEach((st,i)=>{
    const v=x[st.k];
    const done=!!v;
    const isLast=i===last;
    html+='<div style="display:flex;gap:10px">';
    html+='<div style="display:flex;flex-direction:column;align-items:center;flex:none">';
    html+='<div style="width:14px;height:14px;border-radius:50%;border:2px solid '+(done?st.color:'var(--bd)')+';background:'+(done?st.color:'transparent')+';display:flex;align-items:center;justify-content:center;font-size:8px;color:#fff">'+(done?'✓':'')+'</div>';
    if(i<steps.length-1)html+='<div style="width:2px;flex:1;min-height:16px;background:'+(x[steps[i+1].k]?st.color:'var(--bd)')+';opacity:'+(x[steps[i+1].k]?'.85':'.3')+';margin:2px 0"></div>';
    html+='</div>';
    html+='<div style="padding-bottom:'+(isLast?'0':'6px')+'"><div style="font-size:11.5px;font-weight:600;color:'+(done?'var(--t1)':'var(--t3)')+'">'+st.icon+' '+st.label+'</div>';
    html+='<div style="font-size:11px;color:'+(done?'var(--t2)':'var(--t3)')+';font-family:\'JetBrains Mono\',monospace;margin-top:1px">'+(done?v:'— aguardando')+'</div>';
    if(done&&st.por)html+='<div style="font-size:10px;color:var(--t3);margin-top:1px">por '+s(st.por)+'</div>';
    html+='</div></div>';
  });
  html+='</div>';
  return html;
}
function renderTkt(d){const isTI=isTICurrent();let vt=visibleTickets(d);const tktFilter=(document.getElementById('tktFilterStatus')?.value)||'';if(tktFilter)vt=vt.filter(x=>tktStatus(x)===tktFilter);const tktSearch=(document.getElementById('tktSearch')?.value||'').toLowerCase().trim();if(tktSearch)vt=vt.filter(x=>[x.id,x.solicitante,x.assunto,x.desc,x.dept].some(v=>String(v||'').toLowerCase().includes(tktSearch)));if(!isTI&&(document.getElementById('tktScope')?.value)==='all')vt=(d.tickets||[]).slice();const tsel=(window._tktSel||{});document.getElementById('ticketsTable').innerHTML=vt.map(x=>{const isOwner=x.solicitante===user?.nome;const canManage=isTI;const statusLabels=TKT_STATUS_LABEL;let actions=`<button class="btn btn-g btn-sm" onclick="viewTkt('${x.id}')" style="padding:4px 8px;font-size:11px" title="Visualizar chamado">👁️</button> `;if(canManage||isOwner){actions+=`<button class="btn btn-g btn-sm" onclick="editTkt('${x.id}')" style="padding:4px 8px;font-size:11px">✏️</button> `;actions+=`<button class="btn btn-g btn-sm" onclick="delTkt('${x.id}')" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button> `}if(canManage&&!tktIsClosed(x)){if(tktStatus(x)==='Aberto'){actions+=`<button class="btn btn-g btn-sm" onclick="changeTktStatus('${x.id}','Em_analise')" style="padding:4px 8px;font-size:11px;background:rgba(59,130,246,0.1);color:var(--ac)">🔍 Analisar</button> `}if(tktStatus(x)==='Em_analise'||tktStatus(x)==='Aberto'){actions+=`<button class="btn btn-g btn-sm" onclick="changeTktStatus('${x.id}','Atendido')" style="padding:4px 8px;font-size:11px;background:rgba(16,185,129,0.1);color:var(--s)">✅ Atender</button> `}if(tktStatus(x)==='Atendido'){actions+=`<button class="btn btn-g btn-sm" onclick="changeTktStatus('${x.id}','Finalizado')" style="padding:4px 8px;font-size:11px">📦 Finalizar</button> `}if(tktRank(x)<3){actions+=`<button class="btn btn-g btn-sm" onclick="forceCloseTkt('${x.id}')" style="padding:4px 8px;font-size:11px;background:rgba(245,158,11,.12);color:var(--w)" title="Encerrar direto, pulando as etapas intermediárias">⏭️ Encerrar</button> `}}if(isOwner&&tktIsClosed(x)&&!x.rating){actions+=`<button class="btn btn-g btn-sm" onclick="showRatingModal('${x.id}')" style="padding:4px 8px;font-size:11px;background:rgba(139,92,246,0.1);color:#8b5cf6">⭐ Avaliar</button> `}let statusBadge=x.rating?`⭐ ${x.rating}/10 ${bdg(statusLabels[tktStatus(x)]||tktStatus(x))}`:bdg(statusLabels[tktStatus(x)]||tktStatus(x));return`<tr style="${tsel[x.id]?'background:rgba(239,68,68,.08)':''}"><td style="text-align:center">${canManage?`<input type="checkbox" ${tsel[x.id]?'checked':''} onclick="toggleTktSel('${x.id}')">`:''}</td><td class="tp" style="font-family:'JetBrains Mono',monospace">${s(x.id)}</td><td><div style="font-weight:600">${s(x.solicitante)}</div><div style="font-size:10px;color:var(--t3)">${s(x.dept)||'-'}</div></td><td>${s(x.assunto)}</td><td style="max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${s(x.desc||'')}">${s(x.desc)||'-'}</td><td>${bdg(x.prioridade)}</td><td>${statusBadge}</td><td style="padding:8px 6px">${tktTimeline(x)}</td><td style="white-space:nowrap">${actions}</td></tr>`}).join('')||`<tr><td colspan="9" style="text-align:center;padding:36px 16px;color:var(--t3)"><div style="font-size:30px;margin-bottom:8px;opacity:.6">${isTI?'📭':'🎉'}</div><div style="font-size:14px;font-weight:600;color:var(--t2)">${isTI?'Nenhum chamado encontrado':'Você não tem chamados nesta visualização'}</div><div style="font-size:12px;margin-top:6px">${isTI?'Ajuste os filtros ou crie um novo chamado.':'Todos os seus chamados estão em dia.'}</div></td></tr>`;updateTktSelCount();updateTktScopeUI(d,isTI)}

function clearTktFilters(){['tktSearch','tktFilterStatus','tktScope'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=id==='tktScope'?'auto':''});renderTkt(getDB())}

function updateTktScopeUI(d,isTI){
  const sc=visibleTickets(d);
  const o=sc.filter(t=>!tktIsClosed(t)).length;
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v};
  set('tktStatOpen',o);set('tktStatClosed',sc.length-o);
  const hint=document.getElementById('tktScopeHint');
  const selScope=document.getElementById('tktScope');
  const selStatus=document.getElementById('tktFilterStatus');
  /* Historico identico para TODOS os perfis: o escopo nao filtra mais. */
  if(selScope){selScope.disabled=true;selScope.value='all';selScope.style.opacity='.5'}
  if(selStatus)selStatus.style.opacity='1';
  if(hint)hint.textContent='Histórico completo — todos os chamados da empresa';
}

function renderEmp(d){
const colors=['#6366f1','#3b82f6','#06d6a0','#f59e0b','#ef4444','#8b5cf6','#ec4899','#14b8a6','#f97316'];
const canDel=canDelete();
const filter=(document.getElementById('empFilter')?.value||'').toLowerCase().trim();
const filtered=filter?d.employees.filter(e=>`${e.nome} ${e.cargo} ${e.dept} ${e.tel||''} ${e.linha||''} ${e.unidade||''} ${e.admissao||''}`.toLowerCase().includes(filter)):d.employees;

const renderGrid=(list,gridId)=>{
if(!document.getElementById(gridId))return;
document.getElementById(gridId).innerHTML=list.map((e,i)=>{
const realIdx=d.employees.indexOf(e);
return `<div class="card ai d${(realIdx%4)+1}" style="cursor:pointer;position:relative" onclick="viewEmp(${e.id})">
${canDel?`<input type="checkbox" class="emp-check" data-id="${e.id}" onclick="event.stopPropagation();updateEmpSelected()" style="position:absolute;top:8px;right:8px;width:16px;height:16px;accent-color:var(--ac);cursor:pointer;z-index:2">`:''}
<div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">
<div style="width:48px;height:48px;border-radius:12px;background:${e.photo?'transparent':colors[realIdx%colors.length]};display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:16px;overflow:hidden">
${e.photo?`<img src="${s(e.photo)}" style="width:100%;height:100%;object-fit:cover">`:s(e.avatar)}
</div>
<div>
<div style="font-weight:700;font-size:14px">${e.nome}</div>
<div style="font-size:12px;color:var(--t3)">${e.cargo}</div>
</div>
</div>
<div style="font-size:12px;color:var(--t2)">
<div>📕§ ${e.email||'-'}</div>
<div>📘 ${e.tel||'-'}</div>
${e.linha?`<div>🔗 Linha: ${e.linha}</div>`:''}
${e.unidade?`<div>🏢 ${e.unidade}</div>`:''}
${e.admissao?`<div>📕… Admissão: ${e.admissao}</div>`:''}
</div>
<div style="margin-top:10px;display:flex;gap:6px;align-items:center">
${bdg(e.status||'Ativo')}
${canDel?`<button class="btn btn-g btn-sm" onclick="event.stopPropagation();editEmp(${e.id})" style="padding:4px 8px;font-size:11px">✏️</button><button class="btn btn-g btn-sm" onclick="event.stopPropagation();delEmp(${e.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button>`:''}
</div>
</div>`}).join('')
};

renderGrid(filtered,'employeeGrid');
renderGrid(filtered.filter(e=>(e.dept||'').match(/opera|pátio|patio|logist|expedi|Portaria|manuten|EPI/i)),'employeeGridOperacao');
renderGrid(filtered.filter(e=>(e.dept||'').match(/admin|finance|RH|ti|Tecnologia|Qualidade/i)),'employeeGridAdministrativo');
renderGrid(filtered.filter(e=>(e.dept||'').match(/Comercial|vendas|faturamento/i)),'employeeGridComercial');
renderGrid(filtered.filter(e=>!(e.dept||'').match(/opera|pátio|patio|logist|expedi|Portaria|manuten|EPI|admin|finance|RH|ti|Tecnologia|Qualidade|Comercial|vendas|faturamento/i)),'employeeGridOutros');
}

function updateEmpSelected(){
const sel=document.querySelectorAll('.emp-check:checked');
const count=sel.length;
const el=document.getElementById('empSelectedCount');
const btn=document.getElementById('empBulkDelBtn');
const btn2=document.getElementById('empBulkInactiveBtn');
if(count>0){el.style.display='inline';el.textContent=count+' selecionado(s)';btn.style.display='inline-flex';btn2.style.display='inline-flex'}
else{el.style.display='none';btn.style.display='none';btn2.style.display='none'}
}

function bulkDeleteEmp(){
const sel=document.querySelectorAll('.emp-check:checked');
if(!sel.length){toast('Nenhum selecionado','e');return}
const ids=Array.from(sel).map(c=>parseInt(c.dataset.id));
const d=getDB();
const names=ids.map(id=>{const e=d.employees.find(x=>x.id===id);return e?e.nome:'?'});
showConfirm('Excluir '+ids.length+' Funcionários',`Excluir: ${names.map(n=>s(n)).join(', ')}?`,()=>{ids.forEach(id=>{const emp=d.employees.find(x=>x.id===id);if(emp){d.inventory.forEach(i=>{if(i.resp===emp.nome)i.resp='Não atribuído'});d.employees=d.employees.filter(x=>x.id!==id);addLog('delete',`Funcionário excluído em lote: ${emp.nome}`)}});setDB(d);renderAll();toast(ids.length+' excluídos','e')});
}

function bulkSetInactiveEmp(){
const sel=document.querySelectorAll('.emp-check:checked');
if(!sel.length){toast('Nenhum selecionado','e');return}
const ids=Array.from(sel).map(c=>parseInt(c.dataset.id));
const d=getDB();
let count=0;
ids.forEach(id=>{const e=d.employees.find(x=>x.id===id);if(e){e.status='Inativo';count++}});
setDB(d);renderAll();toast(count+' marcados como inativos','w');
}

function removeInactiveEmp(){
const d=getDB();
const inactive=d.employees.filter(e=>{
const st=(e.status||'').toLowerCase();
const nm=(e.nome||'').toUpperCase();
return st==='inativo'||nm.includes('AFASTADO')||nm.includes('AFASTADA')||nm.includes('ABANDONO')||st==='desligado'||st==='demitido'||e.unidade==='AFASTADO';
});
if(!inactive.length){toast('Nenhum inativo/afastado encontrado','i');return}
showConfirm('Remover '+inactive.length+' inativos',`Remover: ${inactive.map(e=>s(e.nome)).join(', ')}?`,()=>{inactive.forEach(e=>{d.inventory.forEach(i=>{if(i.resp===e.nome)i.resp='Não atribuído'});d.employees=d.employees.filter(x=>x.id!==e.id);addLog('delete',`Inativo removido: ${e.nome}`)});setDB(d);renderAll();toast(inactive.length+' removidos!','e')});
}

function showEmpTab(tab,el){
document.querySelectorAll('#sec-funcionarios .tab').forEach(t=>t.classList.remove('active'));
if(el)el.classList.add('active');
document.querySelectorAll('#sec-funcionarios .emp-tab-content').forEach(c=>c.style.display='none');
const target=document.getElementById('empTab-'+tab);
if(target)target.style.display='block';
}

function viewEmp(id){const d=getDB();const e=d.employees.find(x=>x.id===id);if(!e)return;const colors=['#6366f1','#3b82f6','#06d6a0','#f59e0b','#ef4444','#8b5cf6'];const c=colors[id%colors.length];const inv=d.inventory.filter(x=>x.resp===e.nome);const photoHtml=e.photo?`<img src="${e.photo}" style="width:100%;height:100%;object-fit:cover;border-radius:16px">`:e.avatar;const canUploadPhoto=user&&(user.profile==='master'||user.dept==='RH'||user.profile==='admin'||user.profile==='gestor_ti');const photoBtn=canUploadPhoto?`<button class="btn btn-p btn-sm" onclick="uploadEmpPhoto(${e.id})" style="margin-top:8px;width:auto">📕· ${e.photo?'Alterar':'Adicionar'} Foto</button>`:'';document.getElementById('empDetail').innerHTML=`<div class="card"><div class="ph"><div class="pa" style="background:${e.photo?'transparent':c};cursor:${canUploadPhoto?'pointer':'default'}" ${canUploadPhoto?`onclick="uploadEmpPhoto(${e.id})"`:''}>${photoHtml}</div><div class="pi"><div class="pn2">${e.nome}</div><div class="pr">${e.cargo} - ${e.dept}</div>${photoBtn}<div class="pm"><div class="pm-i"><strong>Status:</strong> ${bdg(e.status||'Ativo')}</div><div class="pm-i"><strong>Nascimento:</strong> ${e.nasc?new Date(e.nasc+'T00:00:00').toLocaleDateString('pt-BR'):'-'}</div></div></div></div><div class="dg" style="margin-bottom:24px"><div class="di"><div class="dl">CPF</div><div class="dv">${e.cpf}</div></div><div class="di"><div class="dl">E-mail</div><div class="dv">${e.email}</div></div><div class="di"><div class="dl">Telefone</div><div class="dv">${e.tel||'-'}</div></div><div class="di"><div class="dl">Obs</div><div class="dv">${e.obs||'-'}</div></div></div><div class="ct" style="margin-bottom:16px">Equipamentos (${inv.length})</div>${inv.length?`<table><thead><tr><th>Patrimônio</th><th>SN</th><th>Modelo</th><th>Status</th></tr></thead><tbody>${inv.map(i=>`<tr><td class="tp" style="font-family:'JetBrains Mono',monospace">${i.pat}</td><td style="font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--ac)">${i.sn}</td><td>${i.mm}</td><td>${bdg(i.status)}</td></tr>`).join('')}</tbody></table>`:'<p style="color:var(--t3)">Nenhum equipamento vinculado</p>'}</div>`;showSec('emp-detail')}

function renderUsers(d,filter='all'){const all=[...d.users,...d.pending];const f=filter==='all'?all:all.filter(x=>x.status===filter);const canPhoto=user&&(user.profile==='master'||user.profile==='admin'||user.profile==='gestor_ti');const sel=(window._userSel||{});document.getElementById('usersTable').innerHTML=f.map(u=>`<tr style="${sel[u.id]?'background:rgba(239,68,68,.08)':''}"><td style="text-align:center">${u.id===1?'':`<input type="checkbox" ${sel[u.id]?'checked':''} onclick="toggleUserSel(${u.id})">`}</td><td><div style="display:flex;align-items:center;gap:10px"><div style="width:32px;height:32px;border-radius:8px;background:linear-gradient(135deg,#6366f1,#8b5cf6);display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:11px;overflow:hidden;cursor:${canPhoto?'pointer':'default'};position:relative" ${canPhoto?`onclick="uploadUserPhoto(${u.id})" title="${u.photo?'Clique para trocar foto':'Clique para adicionar foto'}"`:''}>${u.photo?`<img src="${u.photo}" style="width:100%;height:100%;object-fit:cover">`:u.avatar}</div>${canPhoto&&u.photo?`<div style="width:14px;height:14px;border-radius:4px;background:var(--d);display:flex;align-items:center;justify-content:center;font-size:8px;color:#fff;cursor:pointer;position:absolute;bottom:-2px;right:-2px;z-index:3" onclick="event.stopPropagation();removeUserPhoto(${u.id})" title="Remover foto">✕</div>`:''}<div><div style="font-weight:600;font-size:13px">${s(u.nome)}</div><div style="font-size:11px;color:var(--t3)">${s(u.email)}</div></div></div></td><td style="font-family:'JetBrains Mono',monospace;font-size:11px">${s(u.matricula)}</td><td>${s(u.dept)}</td><td>${bdg(profileName(u.profile))}</td><td>${bdg(u.status==='approved'?'Aprovado':u.status==='pending'?'Pendente':'Bloqueado')}</td><td style="display:flex;gap:4px;flex-wrap:wrap">${u.status==='pending'&&canDelete()?`<button class="btn btn-s btn-sm" onclick="approveUser(${u.id})" style="padding:4px 8px;font-size:11px">✓ Aprovar</button><button class="btn btn-d btn-sm" onclick="rejectUser(${u.id})" style="padding:4px 8px;font-size:11px">✝ Rejeitar</button>`:u.id!==1&&u.status==='approved'&&canDelete()?`<button class="btn btn-g btn-sm" onclick="uploadUserPhoto(${u.id})" style="padding:4px 8px;font-size:11px">📕·</button>${u.photo?`<button class="btn btn-d btn-sm" onclick="removeUserPhoto(${u.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button>`:''}<button class="btn btn-g btn-sm" onclick="editUser(${u.id})" style="padding:4px 8px;font-size:11px">✏️</button><button class="btn btn-g btn-sm" onclick="generateResetToken(${u.id})" style="padding:4px 8px;font-size:11px" title="Gerar token para o usuário criar a própria senha">🔐</button><button class="btn btn-g btn-sm" onclick="resetPassword(${u.id})" style="padding:4px 8px;font-size:11px" title="Definir uma senha manualmente">🔑</button><button class="btn btn-g btn-sm" onclick="blockUser(${u.id})" style="padding:4px 8px;font-size:11px">🔧</button>${isMaster()?`<button class="btn btn-p btn-sm" onclick="openPermModal(${u.id})" style="padding:4px 8px;font-size:11px" title="Editar Permissões">🔔</button>`:''}<button class="btn btn-g btn-sm" onclick="deleteUser(${u.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button>`:u.id!==1&&u.status==='blocked'&&canDelete()?`<button class="btn btn-s btn-sm" onclick="blockUser(${u.id})" style="padding:4px 8px;font-size:11px">🔧“ Desbloquear</button><button class="btn btn-d btn-sm" onclick="deleteUser(${u.id})" style="padding:4px 8px;font-size:11px;color:var(--d)">🗑️</button>`:''}</td></tr>`).join('');updateUsersSelCount()}

function filterUsers(f,el){document.querySelectorAll('#sec-usuarios .tab').forEach(t=>t.classList.remove('active'));el.classList.add('active');renderUsers(getDB(),f)}

async function approveUser(id){const d=getDB();const i=d.pending.findIndex(x=>x.id===id);if(i!==-1){const u=d.pending.splice(i,1)[0];const genPass=u.nome.toLowerCase().replace(/\s/g,'')+new Date().getFullYear();u.password='sha256:'+await hashPassword(genPass);u.passwordChangedAt=Date.now();/* `senhaInicial` marca para o servidor que ESTA e a senha inicial da conta nova: sem isso o hash era descartado na fusao e a conta ficava sem senha (login recusado com "senha incorreta"). */u.senhaInicial=true;u.status='approved';u.twofa=false;u.twofaSecret='';u.twofaEnabled=false;u.twofaCodes=[];u.firstLogin=true;u.twofaChangedAt=Date.now();d.users.push(u);setDB(d);const _pushed=await pushToFirebase();if(_pushed===false)toast('Aviso: a senha nao foi confirmada pela nuvem. Verifique a sincronização.','w');addLog('approve',`Usuário aprovado: ${u.nome} | Senha: ${genPass}`);const creds='Login: '+u.email+' | Senha: '+genPass;showConfirm('Usuário Aprovado!',`<div style="text-align:left"><div style="margin-bottom:12px"><strong>${s(u.nome)}</strong> foi aprovado!</div><div style="margin-bottom:12px"><strong>Login:</strong> ${s(u.email)}</div><div style="margin-bottom:12px"><strong>Senha:</strong> <span style="font-family:monospace;background:var(--bg);padding:4px 8px;border-radius:4px">${genPass}</span></div><button class="btn btn-p btn-sm" onclick="navigator.clipboard.writeText('${creds.replace(/'/g,"\\'")}');toast('Copiado!','s')" style="width:auto;margin-top:8px">📟 Copiar Credenciais</button></div>`,()=>{});renderAll()}}

function rejectUser(id){const d=getDB();const u=d.pending.find(x=>x.id===id);d.pending=d.pending.filter(x=>x.id!==id);setDB(d);addLog('reject',`Solicitação rejeitada: ${u?.nome}`);renderAll();toast('Rejeitado','e')}

function editUser(id){const d=getDB();const u=d.users.find(x=>x.id===id);if(!u||u.id===1)return;const newNome=prompt('Nome:',u.nome);if(!newNome)return;const newDept=prompt('Departamento:',u.dept);const newProfile=prompt('Perfil (master/admin/gestor_ti/tecnico/gestor/funcionario):',u.profile);if(newNome)u.nome=newNome;if(newDept)u.dept=newDept;if(newProfile)u.profile=newProfile;setDB(d);addLog('update',`Usuário editado: ${u.nome}`);renderAll();toast('Usuário editado!','s')}

function deleteUser(id){const d=getDB();const u=[...d.users,...d.pending].find(x=>x.id===id);if(!u||u.id===1)return;showConfirm('Excluir',`Excluir ${s(u.nome)}?`,()=>{d.users=d.users.filter(x=>x.id!==id);d.pending=d.pending.filter(x=>x.id!==id);if(u.email&&!(d.deletedEmails||[]).includes(u.email))d.deletedEmails=(d.deletedEmails||[]).concat([u.email]);addLog('delete',`Usuário excluído: ${u.nome}`);setDB(d);pushToFirebase();renderAll();toast('Excluído','e')})}

function toggleUserSel(id){if(!window._userSel)window._userSel={};if(window._userSel[id])delete window._userSel[id];else window._userSel[id]=true;renderUsers(getDB())}

function updateUsersSelCount(){const n=window._userSel?Object.keys(window._userSel).filter(k=>window._userSel[k]).length:0;const el=document.getElementById('usersSelCount');if(el)el.textContent=n;const sa=document.getElementById('usersSelAll');if(sa)sa.checked=n>0}

function toggleSelectAllUsers(){const d=getDB();const all=[...d.users,...d.pending];const cb=document.getElementById('usersSelAll');if(!window._userSel)window._userSel={};if(cb&&cb.checked){all.forEach(u=>{if(u.id!==1)window._userSel[u.id]=true})}else{window._userSel={}}renderUsers(getDB())}

function bulkDeleteUsers(){const sel=window._userSel||{};const ids=Object.keys(sel).filter(k=>sel[k]);if(ids.length===0){toast('Selecione Usuários primeiro','e');return}const d=getDB();const alvo=[...d.users,...d.pending].filter(u=>u.id!==1&&sel[u.id]);if(alvo.length===0){toast('Nenhum usuário selecionado válido','e');return}const emails=[...new Set(alvo.map(u=>u.email).filter(Boolean))];showConfirm('Excluir em massa',`Excluir <b>${alvo.length}</b> usuário(s)?<br><div style="font-size:11px;color:var(--t3);margin-top:6px;max-height:120px;overflow:auto">${alvo.map(u=>s(u.nome)+' <span style="opacity:.6">'+s(u.email)+'</span>').join('<br>')}</div>`,()=>{d.users=d.users.filter(x=>!(sel[x.id]&&x.id!==1));d.pending=d.pending.filter(x=>!(sel[x.id]&&x.id!==1));d.deletedEmails=(d.deletedEmails||[]).concat(emails.filter(e=>!(d.deletedEmails||[]).includes(e)));if(d.deletedEmails.length>300)d.deletedEmails=d.deletedEmails.slice(-300);addLog('delete',`Exclusão em massa: ${alvo.length} Usuários`);setDB(d);window._userSel={};pushToFirebase();renderAll();toast(`Excluídos ${alvo.length} Usuários`,'e')})}

function blockUser(id){const d=getDB();const u=d.users.find(x=>x.id===id);if(u){u.status=u.status==='blocked'?'approved':'blocked';setDB(d);addLog('block',`Usuário ${u.status}: ${u.nome}`);renderUsers(d);toast(u.status==='blocked'?'Bloqueado':'Desbloqueado','w')}}

async function resetPassword(id){const d=getDB();const u=d.users.find(x=>x.id===id);if(u&&id!==1){const newPass=prompt(`Defina nova senha para ${u.nome}:`,u.nome.toLowerCase().replace(/\s/g,'')+new Date().getFullYear());if(!newPass)return;let _pwdOk2=false;
  try{
    const _rp2=await apiCall(API_AUTH+'?op=password',{method:'POST',body:{userId:String(id),senha:newPass}});
    _pwdOk2=!!(_rp2&&_rp2.ok);
  }catch(_e){ _pwdOk2=false; }
  if(!_pwdOk2){toast('Nao foi possivel redefinir a senha. Tente novamente.','e');return}
  u.password='sha256:'+await hashPassword(newPass);u.twofaEnabled=false;u.twofaSecret='';u.twofaCodes=[];u.firstLogin=true;u.twofaChangedAt=Date.now();u.passwordChangedAt=Date.now();setDB(d);try{const _okp=await pushToFirebase();if(_okp===false)toast('Aviso: nuvem ainda não atualizada. O reset vale localmente e a sincronização continua em segundo plano.','w')}catch(e){}addLog('password_reset',`Senha resetada: ${u.nome} | 2FA reiniciado`);const creds='Login: '+u.email+' | Senha: '+newPass;showConfirm('Senha Resetada!',`<div style="text-align:left"><div style="margin-bottom:12px"><strong>Nova senha de ${s(u.nome)}:</strong></div><div style="margin-bottom:12px"><span style="font-family:monospace;background:var(--bg);padding:4px 8px;border-radius:4px">${newPass}</span></div><div style="margin-bottom:12px">⚠️ O 2FA foi reiniciado. O funcionário deverá configurar novamente.</div><button class="btn btn-p btn-sm" onclick="navigator.clipboard.writeText('${creds.replace(/'/g,"\\'")}');toast('Copiado!','s')" style="width:auto;margin-top:8px">📟 Copiar Credenciais</button></div>`,()=>{});toast('Senha resetada!','s')}}

function updatePendingBadge(d){const c=d.pending.length;document.getElementById('pendingBadge').textContent=c;document.getElementById('pendingBadge').style.display=c>0?'inline':'none'}

function updateChatBadge(){
  if(!['master','admin','gestor_ti','tecnico'].includes(user?.profile)&&user?.dept!=='Tecnologia')return;
  const d=getDB();
  const lastRead=parseInt(localStorage.getItem('Chat_lastRead_'+user?.id)||'0');
  const newMsgs=(d.messages||[]).filter(m=>m.user!==user?.nome&&m.time&&(new Date(m.time).getTime()>lastRead));
  const c=newMsgs.length;
  const badge=document.getElementById('ChatBadge');
  if(badge){badge.textContent=c;badge.style.display=c>0?'inline':'none'}
}
function markChatRead(){localStorage.setItem('Chat_lastRead_'+user?.id,Date.now().toString());const badge=document.getElementById('ChatBadge');if(badge){badge.textContent='0';badge.style.display='none'}}

function printLabelById(id){const d=getDB();const x=(d.inventory||[]).find(i=>String(i.id)===String(id));if(!x)return;printLabel(x.pat||'',x.sn||'',x.mm||'')}
function renderLabels(d){document.getElementById('labelsGrid').innerHTML=d.inventory.map((x,i)=>{const code=x.sn||x.pat;const cid='lbl_'+i;return`<div class="card" style="text-align:center;padding:20px"><div style="font-size:8px;color:var(--t3);letter-spacing:3px;margin-bottom:6px">GALVABRAS</div><div style="font-size:14px;font-weight:800;font-family:'JetBrains Mono',monospace;margin:6px 0">${s(x.pat)}</div><div style="display:flex;justify-content:center;margin:8px 0"><canvas id="${cid}" style="max-width:180px;height:50px"></canvas></div><div style="font-size:6px;color:var(--t3);font-family:monospace;margin-bottom:6px">${code}</div><div style="font-size:12px;font-weight:600">${s(x.mm||'-')}</div><div style="font-size:10px;color:var(--t3);font-family:monospace">SN: ${s(x.sn||'-')}</div><button class="btn btn-g btn-sm" onclick="printLabelById(${JSON.stringify(String(x.id))})" style="margin-top:10px;width:auto">🖨️ Imprimir A4</button></div>`}).join('');setTimeout(()=>{try{d.inventory.forEach((x,i)=>{const c=document.getElementById('lbl_'+i);if(c&&window.JsBarcode){JsBarcode(c,x.sn||x.pat,{format:'CODE128',width:1.5,height:40,displayValue:true,fontSize:8,margin:1})}})}catch(e){console.error('Barcode preview error:',e)}},0)}

function code128SVG(text,w,h){
  try{
    const id='bc_'+Math.random().toString(36).substr(2,8);
    const tmp=document.createElement('canvas');
    tmp.style.display='none';
    tmp.id=id;
    document.body.appendChild(tmp);
    JsBarcode('#'+id,text,{format:'CODE128',width:2,height:h||50,displayValue:false,margin:0,flat:true});
    const svgNS='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(svgNS,'svg');
    svg.setAttribute('viewBox','0 0 '+tmp.width+' '+tmp.height);
    svg.setAttribute('style','width:'+w+'px;height:'+(h||50)+'px');
    const img=document.createElementNS(svgNS,'image');
    img.setAttribute('href',tmp.toDataURL('image/png'));
    img.setAttribute('width',tmp.width);
    img.setAttribute('height',tmp.height);
    svg.appendChild(img);
    document.body.removeChild(tmp);
    return svg.outeRHTML;
  }catch(e){return'<div style="width:'+w+'px;height:'+(h||50)+'px;background:#eee;display:flex;align-items:center;justify-content:center;font-size:10px;color:#999">Erro barcode</div>'}
}

function printLabel(pat,sn,mm){
  const code=sn||pat;
  const w=window.open('','','width=800,height=600');
  w.document.write(`<!DOCTYPE html>
<html><head><title>Etiqueta ${pat}</title>
<style>
  @page{size:A4;margin:10mm}
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:'Segoe UI',Arial,sans-serif;background:#fff;padding:0;margin:0}
  .label-sheet{width:210mm;min-height:297mm;padding:10mm;display:flex;flex-wrap:wrap;gap:8mm;justify-content:flex-start;align-content:flex-start}
  .label{width:88mm;height:32mm;border:1.5px solid #222;border-radius:3mm;padding:3mm 4mm;display:flex;flex-direction:column;justify-content:space-between;page-break-inside:avoid;overflow:hidden}
  .label-header{display:flex;justify-content:space-between;align-items:flex-start}
  .label-company{font-size:6pt;font-weight:700;letter-spacing:2px;color:#555;text-transform:uppercase}
  .label-id{font-size:5.5pt;color:#888;font-family:'Courier New',monospace}
  .label-code{font-size:11pt;font-weight:800;font-family:'Courier New',monospace;color:#000;text-align:center;letter-spacing:1px;line-height:1.1}
  .barcode-wrap{text-align:center;margin:1mm 0}
  .label-footer{display:flex;justify-content:space-between;align-items:flex-end}
  .label-model{font-size:7pt;font-weight:600;color:#333}
  .label-sn{font-size:6pt;color:#666;font-family:'Courier New',monospace}
  .label-dept{font-size:5.5pt;color:#999;font-style:italic}
  .label-footer-right{text-align:right}
  @media print{body{padding:0;margin:0;background:#fff}.label-sheet{padding:10mm}.label{border-color:#000}}
</style></head>
<body>
<div class="label-sheet">
${Array(6).fill(0).map((_,i)=>`<div class="label">
    <div class="label-header">
      <div>
        <div class="label-company"><img src="${GG_LOGO_DURL}" alt="Grupo Galva" style="height:5mm;display:block"></div>
        <div class="label-id">ID: ${pat}</div>
      </div>
      <div class="label-footer-right">
        <div class="label-model">${mm||'-'}</div>
      </div>
    </div>
    <div class="label-code">${pat}</div>
    <div class="barcode-wrap"><svg class="bc" data-code="${code}"></svg></div>
    <div class="label-footer">
      <div class="label-sn">SN: ${sn||'-'}</div>
      <div class="label-dept">Gestão de TI</div>
    </div>
  </div>`).join('')}
</div>
<\/script><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script>
<script>
function tryBarcode(){
  if(typeof JsBarcode==='undefined'){setTimeout(tryBarcode,200);return}
  document.querySelectorAll('.bc').forEach(function(el){
    try{JsBarcode(el,el.dataset.code,{format:'CODE128',width:2,height:40,displayValue:true,fontSize:10,margin:2})}
    catch(e){el.outerHTML='<div style="padding:4px;font-size:10px;border:1px solid #ccc">'+el.dataset.code+'</div>'}
  });
  setTimeout(function(){window.print();window.close()},500);
}
tryBarcode();
<\/script>
</body></html>`);
  w.document.close();
}

