toast('Gerando PDF...','i');const pages=document.querySelectorAll('.qq-tabpage');const prev=[];pages.forEach((p,i)=>{prev[i]=p.style.display;p.style.display='block'});await new Promise(r=>setTimeout(r,400));window._qualNoAnim=true;qualityRender(true);window._qualNoAnim=false;await new Promise(r=>setTimeout(r,400));
const{jsPDF}=window.jspdf;const doc=new jsPDF('l','mm','a4');ggLogo(doc,152,14,14);const PW=297,ML=10,MR=287,USABLE=MR-ML;const now=new Date().toLocaleString('pt-BR');
