header();
doc.setFontSize(19);doc.setFont('helvetica','bold');doc.setTextColor(240,130,32);doc.text('GALVABRAS - QUALIDADE INDUSTRIAL',ML,22);doc.setFontSize(10);doc.setFont('helvetica','normal');doc.setTextColor(143,143,143);doc.text('Relatorio de Retrabalhos e Contencoes',ML,28);doc.text('Periodo: '+d0+' a '+d1,MR,18,{align:'right'});doc.text('Emissao: '+now,MR,23,{align:'right'});doc.setDrawColor(240,130,32);doc.setLineWidth(0.5);doc.line(ML,31,MR,31);
