function uploadQualidadeExcel(e){const file=e.target.files[0];if(!file)return;const d=getDB();if(!d.QualidadeDocs)d.QualidadeDocs=[];const reader=new FileReader();reader.onload=function(ev){d.QualidadeDocs.push({id:Date.now(),name:file.name,size:(file.size/1024).toFixed(1)+'KB',type:'Excel',data:ev.target.result,time:new Date().toLocaleString('pt-BR'),user:user?user.nome:'Sistema'});setDB(d);pushToFirebase();toast('Documento Qualidade enviado!','s');addLog('upload','Excel Qualidade: '+file.name)};reader.readAsDataURL(file);e.target.value=''}
