function renderComercialDocs(){const d=getDB();const el=document.getElementById('ComercialDocsList');if(!el)return;const docs=(d.ComercialDocs||[]).slice(-20).reverse();el.innerHTML=docs.length?docs.map(x=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--bd)"><div style="display:flex;align-items:center;gap:10px"><span style="font-size:20px">${x.type==='PDF'?'📄':'📋'}</span><div><div style="font-weight:600;font-size:13px">${x.name}</div><div style="font-size:11px;color:var(--t3)">${x.type} • ${x.size} • ${x.user} • ${x.time}</div></div></div><div style="display:flex;gap:4px"><button class="btn btn-g btn-sm" onclick="downloadDoc('${encodeURIComponent(JSON.stringify({name:x.name,data:x.data,type:x.type}))}')" style="font-size:11px;padding:4px 8px;text-decoration:none">⬡</button><button class="btn btn-d btn-sm" onclick="delComercialDoc(${x.id})" style="font-size:11px;padding:4px 8px">🗑️</button></div></div>`).join(''):'<p style="color:var(--t3);font-size:13px;text-align:center;padding:20px">Nenhum documento Comercial enviado</p>'}

