function downloadDoc(encoded){const tokenVal=document.getElementById('reportTokenInput')?.value?.trim();if(!tokenVal){toast('Solicite e insira um token de autorização para baixar o arquivo','e');return}const d=getDB();const validToken=(d.reportTokens||[]).find(t=>t.token===tokenVal&&t.used===false);if(!validToken){toast('Token inválido ou já utilizado. Solicite um novo.','e');return}const now=Date.now();if(validToken.type==='relatorio'&&validToken.expiresAt&&now>validToken.expiresAt){validToken.status='Expirado';setDB(d);toast('Token expirado! Solicite um novo.','e');return}validToken.used=true;validToken.usedAt=new Date().toLocaleString('pt-BR');setDB(d);addLog('download',`Download de documento: ${validToken.token}`);try{const info=JSON.parse(decodeURIComponent(encoded));const parts=info.data.split(',');const mime=parts[0].match(/:(.*?);/)[1];const b64=parts[1];const byteStr=atob(b64);const arr=new Uint8Array(byteStr.length);for(let i=0;i<byteStr.length;i++)arr[i]=byteStr.charCodeAt(i);const blob=new Blob([arr],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=info.name;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);toast('Download iniciado!','s')}catch(e){toast('Erro ao baixar arquivo','e')}}

function openBulkEdit(){const d=getDB();const prefixes={};d.inventory.forEach(x=>{if(x.pat){const m=x.pat.match(/^([A-Z0-9]+-\d{4}-[A-Z]+)\d+$/);if(m){const p=m[1];if(!prefixes[p])prefixes[p]=0;prefixes[p]++}}});const sel=document.getElementById('bulkPrefix');sel.innerHTML='<option value="">Selecione o lote...</option>';Object.keys(prefixes).sort().forEach(p=>{sel.innerHTML+='<option value="'+p+'">'+p+' ('+prefixes[p]+' itens)</option>'});document.getElementById('bulkBrand').value='';document.getElementById('bulkModel').value='';document.getElementById('bulkSN').value='';document.getElementById('bulkDept').value='';document.getElementById('bulkStatus').value='';document.getElementById('bulkResp').value='';document.getElementById('bulkCount').textContent='';document.getElementById('modalBulkEdit').classList.add('show')}

function openBatchModal(){document.getElementById('mtInv').textContent='Cadastro de Patrimônio em Lote';document.getElementById('iId').value='';document.getElementById('iPat').value='';document.getElementById('iPat').disabled=true;document.getElementById('iPat').placeholder='Gerado automaticamente';document.getElementById('iSN').value='';document.getElementById('iType').value='Monitor';document.getElementById('iBrand').value='';document.getElementById('iModel').value='';document.getElementById('iDept').value='Tecnologia';document.getElementById('iResp').value='';document.getElementById('iVal').value='';document.getElementById('iStatus').value='Estoque';document.getElementById('iDate').value=new Date().toISOString().split('T')[0];const bf=document.getElementById('batchFields');if(bf)bf.style.display='block';const qty=document.getElementById('iQty');if(qty){qty.value='2';qty.removeAttribute('min')}const vb=document.getElementById('iValBatch');if(vb)vb.value='';document.getElementById('batchPreview').style.display='none';document.getElementById('modalInv').classList.add('show');setTimeout(updatePatPreview,100)}

function filterInventory(){const d=getDB();const search=(document.getElementById('invSearchFilter')?.value||'').toLowerCase();const typeFilter=document.getElementById('invTypeFilter')?.value||'';const statusFilter=document.getElementById('invStatusFilter')?.value||'';let filtered=d.inventory;if(search){filtered=filtered.filter(x=>(x.pat||'').toLowerCase().includes(search)||(x.eq||'').toLowerCase().includes(search)||(x.mm||'').toLowerCase().includes(search)||(x.brand||'').toLowerCase().includes(search)||(x.resp||'').toLowerCase().includes(search))}if(typeFilter){filtered=filtered.filter(x=>x.eq===typeFilter)}if(statusFilter){filtered=filtered.filter(x=>x.status===statusFilter)}renderInvTable(filtered)}

function loadBulkItems(){const prefix=document.getElementById('bulkPrefix').value;const d=getDB();if(!prefix){document.getElementById('bulkCount').textContent='';return}const items=d.inventory.filter(x=>x.pat&&x.pat.startsWith(prefix));document.getElementById('bulkCount').textContent=items.length+' itens encontrados com prefixo '+prefix}

function applyBulkEdit(){const prefix=document.getElementById('bulkPrefix').value;if(!prefix){toast('Selecione um lote','e');return}const brand=document.getElementById('bulkBrand').value;const model=document.getElementById('bulkModel').value;const sn=document.getElementById('bulkSN').value;const dept=document.getElementById('bulkDept').value;const status=document.getElementById('bulkStatus').value;const resp=document.getElementById('bulkResp').value;if(!brand&&!model&&!sn&&!dept&&!status&&!resp){toast('Preencha pelo menos um campo','e');return}const d=getDB();let count=0;let snCounter=1;d.inventory.forEach(x=>{if(x.pat&&x.pat.startsWith(prefix)){if(brand)x.brand=brand;if(model)x.mm=model;if(dept)x.dept=dept;if(status)x.status=status;if(resp)x.resp=resp;if(sn){x.sn=sn+'-'+String(snCounter).padStart(3,'0');snCounter++}count++}});addLog('update',`Edição em lote: ${count} itens do prefixo ${prefix}`);setDB(d);pushToFirebase();closeModal('modalBulkEdit');renderAll();toast(count+' itens atualizados!','s')}

function requestPDFToken(type){pendingPrintAction=type;document.getElementById('printTokenInput').value='';document.getElementById('modalPrintToken').classList.add('show');window._printMode='pdf'}

function validatePrintToken(){const input=document.getElementById('printTokenInput').value.trim();const d=getDB();const t=d.Tokens.find(x=>x.full===input&&x.status==='Ativo'&&x.type==='Impressão');if(!t){toast('Token inválido ou expirado!','e');return}if(t.expiresAt&&Date.now()>t.expiresAt){t.status='Expirado';setDB(d);toast('Token expirado! Gere um novo.','e');return}closeModal('modalPrintToken');addLog('print',`Relatório impresso via token: ${pendingPrintAction}`);doPrint(pendingPrintAction);toast('Impressão liberada!','s')}

function doPrint(type){const d=getDB();let html='';const now=new Date().toLocaleDateString('pt-BR');if(type==='inventario'){html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Inventário</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Total: ${d.inventory.length} itens</p></div></div><table><thead><tr><th>Patrimônio</th><th>SN</th><th>Equipamento</th><th>Modelo</th><th>Depto</th><th>Responsável</th><th>Status</th><th>Valor</th></tr></thead><tbody>${d.inventory.map(x=>`<tr><td>${x.pat}</td><td>${x.sn}</td><td>${x.eq}</td><td>${x.mm}</td><td>${x.dept}</td><td>${x.resp||'-'}</td><td>${x.status}</td><td>${x.val||'-'}</td></tr>`).join('')}</tbody></table>`}else if(type==='funcionarios'){html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Funcionários</p></div><div style="text-align:right"><p>Data: ${now}</p></div></div><table><thead><tr><th>Nome</th><th>CPF</th><th>Cargo</th><th>Depto</th><th>Telefone</th><th>Nascimento</th></tr></thead><tbody>${d.employees.map(x=>`<tr><td>${x.nome}</td><td>${x.cpf}</td><td>${x.cargo}</td><td>${x.dept}</td><td>${x.tel||'-'}</td><td>${x.nasc?new Date(x.nasc+'T00:00:00').toLocaleDateString('pt-BR'):'-'}</td></tr>`).join('')}</tbody></table>`}else if(type==='Chamados'){const tickets=d.tickets||[];const total=tickets.length;const abertos=tickets.filter(x=>x.status==='Aberto').length;const emAnalise=tickets.filter(x=>x.status==='Em_analise').length;const atendidos=tickets.filter(x=>x.status==='Atendido').length;const finalizados=tickets.filter(x=>x.status==='Finalizado').length;const rated=tickets.filter(x=>x.rating);const avgRating=rated.length?(rated.reduce((a,x)=>a+x.rating,0)/rated.length).toFixed(1):'-';const maxBar=Math.max(abertos,emAnalise,atendidos,finalizados,1);const barW=40;html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Chamados</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Total: ${total} chamados</p><p>Avaliação Média: ${avgRating}/10</p></div></div><div style="margin-bottom:20px;padding:16px;border:1px solid #ddd;border-radius:8px"><h3 style="margin:0 0 12px;font-size:14px;color:#2563eb">📈 Desempenho dos Chamados</h3><div style="display:flex;align-items:flex-end;gap:20px;height:120px;margin-bottom:10px"><div style="text-align:center;flex:1"><div style="background:#3b82f6;height:${Math.round((abertos/maxBar)*100)}px;border-radius:4px 4px 0 0;min-height:2px"></div><div style="font-size:10px;margin-top:4px;font-weight:700">${abertos}</div><div style="font-size:9px;color:#666">Abertos</div></div><div style="text-align:center;flex:1"><div style="background:#f59e0b;height:${Math.round((emAnalise/maxBar)*100)}px;border-radius:4px 4px 0 0;min-height:2px"></div><div style="font-size:10px;margin-top:4px;font-weight:700">${emAnalise}</div><div style="font-size:9px;color:#666">Em Análise</div></div><div style="text-align:center;flex:1"><div style="background:#8b5cf6;height:${Math.round((atendidos/maxBar)*100)}px;border-radius:4px 4px 0 0;min-height:2px"></div><div style="font-size:10px;margin-top:4px;font-weight:700">${atendidos}</div><div style="font-size:9px;color:#666">Atendidos</div></div><div style="text-align:center;flex:1"><div style="background:#10b981;height:${Math.round((finalizados/maxBar)*100)}px;border-radius:4px 4px 0 0;min-height:2px"></div><div style="font-size:10px;margin-top:4px;font-weight:700">${finalizados}</div><div style="font-size:9px;color:#666">Finalizados</div></div></div><div style="display:flex;gap:20px;font-size:11px;color:#555"><span>Total: ${total}</span><span>Avaliados: ${rated.length}</span><span>Média: ${avgRating}/10</span></div></div><table><thead><tr><th>ID</th><th>Solicitante</th><th>Departamento</th><th>Assunto</th><th>Descrição</th><th>Categoria</th><th>Prioridade</th><th>Status</th><th>Avaliação</th></tr></thead><tbody>${tickets.map(x=>`<tr><td>${x.id}</td><td>${x.solicitante||'-'}</td><td>${x.dept||'-'}</td><td>${x.assunto||'-'}</td><td style="max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${(x.desc||'').substring(0,60)}${(x.desc||'').length>60?'...':''}</td><td>${x.categoria||'-'}</td><td>${x.prioridade||'-'}</td><td>${x.status||'-'}</td><td>${x.rating?x.rating+'/10':'-'}</td></tr>`).join('')}</tbody></table>`}else if(type==='Estoque'){html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Estoque</p></div><div style="text-align:right"><p>Data: ${now}</p></div></div><table><thead><tr><th>Item</th><th>Categoria</th><th>Entradas</th><th>Saídas</th><th>Saldo</th><th>Status</th></tr></thead><tbody>${d.stock.map(x=>`<tr><td>${x.name}</td><td>${x.cat}</td><td>${x.ent}</td><td>${x.sai}</td><td>${x.saldo}</td><td>${x.status}</td></tr>`).join('')}</tbody></table>`}else if(type==='patrimonio-setor'||type==='patrimonio-func'){html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Inventário</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Total: ${d.inventory.length} itens</p></div></div><table><thead><tr><th>Patrimônio</th><th>SN</th><th>Equipamento</th><th>Modelo</th><th>Depto</th><th>Responsável</th><th>Status</th><th>Valor</th></tr></thead><tbody>${d.inventory.map(x=>`<tr><td>${x.pat}</td><td>${x.sn}</td><td>${x.eq}</td><td>${x.mm}</td><td>${x.dept}</td><td>${x.resp||'-'}</td><td>${x.status}</td><td>R$ ${(parseFloat(x.val)||0).toFixed(2)}</td></tr>`).join('')}</tbody></table>`}else if(type==='manutencao'){const items=d.inventory.filter(x=>x.status==='Manutenção');html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Manutenção</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Itens: ${items.length}</p></div></div><table><thead><tr><th>Patrimônio</th><th>Equipamento</th><th>Modelo</th><th>Depto</th><th>Responsável</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr><td>${x.pat}</td><td>${x.eq}</td><td>${x.mm}</td><td>${x.dept}</td><td>${x.resp||'-'}</td><td>${x.status}</td></tr>`).join('')}</tbody></table>`}else if(type==='valor'){const total=d.inventory.reduce((s,x)=>s+(parseFloat(x.val)||0),0);const byDept={};d.inventory.forEach(x=>{const dp=x.dept||'Não definido';byDept[dp]=(byDept[dp]||0)+(parseFloat(x.val)||0)});html=`<div class="header"><div><h1>GALVABRAS</h1><p>Consolidação Financeira</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Valor Total: R$ ${total.toFixed(2)}</p></div></div><div style="margin-bottom:20px;padding:16px;background:#f0f4f8;border-radius:8px;text-align:center"><div style="font-size:28px;font-weight:800;color:#3b82f6">R$ ${total.toFixed(2)}</div></div><table><thead><tr><th>Departamento</th><th>Valor</th><th>%</th></tr></thead><tbody>${Object.entries(byDept).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${k}</td><td>R$ ${v.toFixed(2)}</td><td>${total>0?((v/total)*100).toFixed(1):'0'}%</td></tr>`).join('')}</tbody></table>`}else if(type==='notasfiscais'){html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Notas Fiscais</p></div><div style="text-align:right"><p>Data: ${now}</p></div></div><table><thead><tr><th>Código</th><th>Descrição</th><th>Categoria</th><th>Qtd</th><th>Valor Unit.</th><th>Valor Total</th><th>NF</th></tr></thead><tbody>${(d.nfItems||[]).map(x=>`<tr><td>${x.codigo}</td><td>${x.descricao}</td><td>${x.categoria||'-'}</td><td>${x.quantidade||1}</td><td>R$ ${x.valorUnit||'0.00'}</td><td>R$ ${x.valorTotal||'0.00'}</td><td>${x.nfNumero||'-'}</td></tr>`).join('')}</tbody></table>`}else if(type==='amoxarifado'){const chamados=d.chamadosAlmox||[];const total=chamados.length;const abertos=chamados.filter(x=>x.status==='Aberto').length;const emSep=chamados.filter(x=>x.status==='Em_Separacao').length;const separados=chamados.filter(x=>x.status==='Separado').length;html=`<div class="header"><div><h1>GALVABRAS</h1><p>Relatório de Chamados - Almoxarifado</p></div><div style="text-align:right"><p>Data: ${now}</p><p>Total: ${total} chamados</p></div></div><div style="margin-bottom:20px;padding:16px;border:1px solid #ddd;border-radius:8px"><h3 style="margin:0 0 12px;font-size:14px;color:#E8611A">📦 Resumo</h3><div style="display:flex;gap:30px;font-size:13px"><div><strong style="color:#ef4444">${abertos}</strong> Abertos</div><div><strong style="color:#f59e0b">${emSep}</strong> Em Separação</div><div><strong style="color:#10b981">${separados}</strong> Separados</div></div></div><table><thead><tr><th>ID</th><th>Solicitante</th><th>Depto</th><th>Itens</th><th>Status</th><th>Separado Por</th><th>Data</th></tr></thead><tbody>${chamados.map(x=>`<tr><td>${x.id||'-'}</td><td>${x.solicitante||'-'}</td><td>${x.dept||'-'}</td><td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${(x.itens||[]).map(i=>i.nome+' ('+i.qtd+')').join(', ')}${x.itensLivres?' | '+x.itensLivres:''}</td><td>${x.status||'-'}</td><td>${x.aceitoPor||'-'}</td><td>${x.createdAt||'-'}</td></tr>`).join('')}</tbody></table>`}html+=`<div class="footer"><p>© ${new Date().getFullYear()} GALVABRAS - Jeff Corp © 2026</p></div>`;html=ggLogoPrintHead()+html;const w=window.open('','_blank');w.document.write(`<!DOCTYPE html><html><head><title>GALVABRAS</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial,sans-serif;padding:30px;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:10px}th{background:#f0f0f0;padding:8px;text-align:left;border:1px solid #ddd}td{padding:6px 8px;border:1px solid #ddd}.header{display:flex;justify-content:space-between;border-bottom:2px solid #333;padding-bottom:15px;margin-bottom:20px}.header h1{font-size:20px}.footer{margin-top:30px;padding-top:10px;border-top:1px solid #ccc;font-size:10px;color:#666;text-align:center}</style></head><body>${html}</body></html>`);w.document.close();w.print()}

function exportLogs(){const d=getDB();let content='Data,Usuário,Ação,Detalhe,IP\n';d.Logs.forEach(l=>{content+=`"${l.time}","${l.user}","${l.action}","${l.detail}","${l.ip}"\n`});const blob=new Blob([content],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Logs_${new Date().toISOString().split('T')[0]}.csv`;a.click();addLog('export','Logs exportados para CSV');toast('Logs exportados!','s')}

function openModal(type,id){if(type==='employee'&&(canCreate()||user.profile==='funcionario')){const d=getDB();if(id){const e=d.employees.find(x=>x.id===id);document.getElementById('mtEmp').textContent='Editar Funcionário';document.getElementById('eId').value=e.id;document.getElementById('eNome').value=e.nome;document.getElementById('eCargo').value=e.cargo;document.getElementById('eCPF').value=e.cpf;document.getElementById('eDept').value=e.dept;document.getElementById('eTel').value=e.tel||'';document.getElementById('eEmail').value=e.email;document.getElementById('eNasc').value=e.nasc||'';document.getElementById('eObs').value=e.obs||'';document.getElementById('ePhoto').value=e.photo||'';if(e.photo){document.getElementById('photoPreview').innerHTML=`<img src="${e.photo}" style="width:100%;height:100%;object-fit:cover">`}else{document.getElementById('photoPreview').innerHTML='<span id="photoIcon">📕·</span>'}const photoField=document.getElementById('photoField');if(user.profile!=='master'&&user.dept!=='RH'&&user.profile!=='admin'&&user.profile!=='gestor_ti'){photoField.style.display='none'}else{photoField.style.display='block';photoField.style.opacity='1';photoField.style.pointerEvents='auto'}}else{document.getElementById('mtEmp').textContent='Novo Funcionário';document.getElementById('eId').value='';document.getElementById('ePhoto').value='';document.getElementById('photoPreview').innerHTML='<span id="photoIcon">📕·</span>';document.querySelectorAll('#modalEmp .fi').forEach(x=>x.value='');const photoField=document.getElementById('photoField');if(user.profile!=='master'&&user.dept!=='RH'&&user.profile!=='admin'&&user.profile!=='gestor_ti'){photoField.style.display='none'}else{photoField.style.display='block';photoField.style.opacity='1';photoField.style.pointerEvents='auto'}}document.getElementById('modalEmp').classList.add('show')}else if(type==='inventory'&&canCreate()){const d=getDB();if(id){const i=d.inventory.find(x=>x.id===id);document.getElementById('mtInv').textContent='Editar Patrimônio';document.getElementById('iId').value=i.id;document.getElementById('iPat').value=i.pat;document.getElementById('iSN').value=i.sn;document.getElementById('iType').value=i.eq;document.getElementById('iBrand').value=i.mm.split(' ')[0];document.getElementById('iModel').value=i.mm;document.getElementById('iDept').value=i.dept;document.getElementById('iResp').value=i.resp||'';document.getElementById('iStatus').value=i.status;document.getElementById('iVal').value=i.val||''}else{document.getElementById('mtInv').textContent='Novo Patrimônio';document.getElementById('iId').value='';document.getElementById('iSN').value=genSN();document.getElementById('iQty').value='1';document.getElementById('iValBatch').value='';document.getElementById('batchFields').style.display='none';document.getElementById('batchPreview').style.display='none';document.getElementById('iPat').disabled=false;document.querySelectorAll('#modalInv .fi:not([readonly])').forEach(x=>{if(x.id!=='iQty'&&x.id!=='iValBatch')x.value=''})}document.getElementById('modalInv').classList.add('show');setTimeout(checkQtyField,50)}else if(type==='stock'&&canCreate()){document.getElementById('mtStk').textContent=id?'Editar Item':'Novo Item';document.getElementById('sId').value=id||'';document.getElementById('modalStk').classList.add('show')}else if(type==='ticket'){document.getElementById('mtTkt').textContent=id?'Editar Chamado':'📕¢ Abrir Chamado';document.getElementById('tId').value=id||'';if(id){const d=getDB();const t=d.tickets.find(x=>x.id==id);if(t){document.getElementById('tReq').value=t.solicitante;document.getElementById('tDept').value=t.dept||'Tecnologia';document.getElementById('tSubj').value=t.assunto;document.getElementById('tDesc').value=t.desc||'';document.getElementById('tPri').value=t.prioridade;document.getElementById('tCat').value=t.categoria||'Hardware';if(document.getElementById('tCli'))document.getElementById('tCli').value=t.cliente||'';if(document.getElementById('tRomaneio'))document.getElementById('tRomaneio').value=t.romaneio||'';if(document.getElementById('tNotaFiscal'))document.getElementById('tNotaFiscal').value=t.notaFiscal||''}}else{document.getElementById('tReq').value=user?.nome||'';document.getElementById('tDept').value=user?.dept||'Tecnologia';document.getElementById('tSubj').value='';document.getElementById('tDesc').value='';document.getElementById('tPri').value='Média';document.getElementById('tCat').value='Hardware';if(document.getElementById('tCli'))document.getElementById('tCli').value='';if(document.getElementById('tRomaneio'))document.getElementById('tRomaneio').value='';if(document.getElementById('tNotaFiscal'))document.getElementById('tNotaFiscal').value=''}tktCategoriaOnChange();document.getElementById('modalTkt').classList.add('show')}else if(!canCreate()){toast('Sem permissão para cadastrar','e')}}

function closeModal(id){document.getElementById(id).classList.remove('show')}

function saveEmp(e){e.preventDefault();const d=getDB();const id=document.getElementById('eId').value;const nome=document.getElementById('eNome').value;const avatar=nome.split(' ').map(x=>x[0]).join('').substring(0,2).toUpperCase();const photo=document.getElementById('ePhoto').value;const data={nome,cargo:document.getElementById('eCargo').value,cpf:document.getElementById('eCPF').value,dept:document.getElementById('eDept').value,tel:document.getElementById('eTel').value,email:document.getElementById('eEmail').value,nasc:document.getElementById('eNasc').value,obs:document.getElementById('eObs').value,avatar,photo:photo||'',eq:0,status:'Ativo'};if(id){const i=d.employees.findIndex(x=>x.id==id);if(i!==-1){const existing=d.employees[i];data.linha=existing.linha||'';data.unidade=existing.unidade||'';data.admissao=existing.admissao||'';d.employees[i]={...existing,...data};addLog('update',`Funcionário atualizado: ${nome}`)}}else{data.id=Date.now();d.employees.push(data);addLog('create',`Novo funcionário: ${nome}`)}setDB(d);closeModal('modalEmp');renderAll();toast(id?'Atualizado!':'Cadastrado!','s')}

function previewPhoto(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Foto deve ter no máximo 5MB','e');return}const reader=new FileReader();reader.onload=function(ev){const img=new Image();img.onload=function(){const canvas=document.createElement('canvas');const maxSize=200;let w=img.width,h=img.height;if(w>maxSize||h>maxSize){if(w>h){h=Math.round(h*maxSize/w);w=maxSize}else{w=Math.round(w*maxSize/h);h=maxSize}}canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);const base64=canvas.toDataURL('image/jpeg',0.7);document.getElementById('ePhoto').value=base64;document.getElementById('photoPreview').innerHTML=`<img src="${base64}" style="width:100%;height:100%;object-fit:cover">`;toast('Foto carregada!','s')};img.src=ev.target.result};reader.readAsDataURL(file)}

function editEmp(id){if(!canCreate()){warnRestricted('editar funcionário');toast('Sem permissão','e');return}openModal('employee',id)}

function delEmp(id){if(!canDelete()){warnRestricted('excluir funcionário');toast('Sem permissão para excluir','e');return}const d=getDB();const e=d.employees.find(x=>x.id===id);if(e){showConfirm('Excluir',`Excluir ${s(e.nome)}?`,()=>{const raw=JSON.parse(localStorage.getItem(DB)||'{}');raw.inventory=(raw.inventory||[]).map(i=>{if(i.resp===e.nome)i.resp='Não atribuído';return i});raw.employees=(raw.employees||[]).filter(x=>x.id!==id);if(!raw.deletedIds)raw.deletedIds=[];const key='employees:'+String(id);if(!raw.deletedIds.includes(key))raw.deletedIds.push(key);if(!raw.Logs)raw.Logs=[];raw.Logs.unshift({id:Date.now(),time:new Date().toLocaleString('pt-BR'),user:user?.nome||'Sistema',action:'delete',detail:'Funcionário excluído: '+e.nome,ip:'local'});if(raw.Logs.length>300)raw.Logs=raw.Logs.slice(0,300);localStorage.setItem(DB,JSON.stringify(raw));pushToFirebase();renderAll();toast('Excluído','e')})}}

function importEmpExcel(e){
  const file=e.target.files[0];
  if(!file)return;
  const reader=new FileReader();
  reader.onload=function(ev){
    try{
      const wb=XLSX.read(ev.target.result,{type:'array'});
      const ws=wb.Sheets[wb.SheetNames[0]];
      const raw=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});
      if(raw.length<2){toast('Planilha vazia ou sem dados','e');return}
      let headerRow=-1;
      let nameCol=-1,funcCol=-1,localCol=-1,lineCol=-1,unitCol=-1,admCol=-1,turnoCol=-1;
      for(let r=0;r<Math.min(15,raw.length);r++){
        const cells=raw[r].map(x=>String(x||'').trim().toUpperCase());
        const joined=cells.join(' ');
        if(joined.includes('FUNÇÃO')||joined.includes('FUNCAO')||joined.includes('CARGO')){
          headerRow=r;
          funcCol=cells.findIndex(h=>h.includes('FUNÇÃO')||h.includes('FUNCAO')||h.includes('CARGO')||h.includes('OCUPAÇÃO'));
          localCol=cells.findIndex(h=>h.includes('LOCAL')||h.includes('DEPART')||h.includes('SETOR')||h.includes('SEÇÃO'));
          lineCol=cells.findIndex(h=>h.includes('LINHA')||h.includes('LINE'));
          unitCol=cells.findIndex(h=>h.includes('UNIDADE')||h.includes('UNIT')||h.includes('FILIAL'));
          admCol=cells.findIndex(h=>h.includes('ADMISSÑO')||h.includes('ADMISSAO')||h.includes('ADMIT'));
          turnoCol=cells.findIndex(h=>h.includes('NOTURNO')||h.includes('TURNO')||h.includes('ADIÇÃO NOTURNO')||h.includes('ADICIONAL'));
          break;
        }
      }
      if(headerRow===-1){
        for(let r=0;r<Math.min(15,raw.length);r++){
          const cells=raw[r].map(x=>String(x||'').trim().toUpperCase());
          if(cells.some(h=>h.includes('NOME'))){
            headerRow=r;
            nameCol=cells.findIndex(h=>h.includes('NOME'));
            funcCol=cells.findIndex(h=>h.includes('CARGO')||h.includes('FUNÇÃO')||h.includes('OCUPAÇÃO'));
            localCol=cells.findIndex(h=>h.includes('LOCAL')||h.includes('DEPART')||h.includes('SETOR'));
            lineCol=cells.findIndex(h=>h.includes('LINHA'));
            unitCol=cells.findIndex(h=>h.includes('UNIDADE')||h.includes('FILIAL'));
            admCol=cells.findIndex(h=>h.includes('ADMISSÑO')||h.includes('ADMISSAO'));
            break;
          }
        }
      }
      const d=getDB();
      let imported=0,skipped=0,updated=0;
      const startRow=headerRow+1;
      for(let i=startRow;i<raw.length;i++){
        const row=raw[i];
        if(!row)continue;
        let nome='';
        if(nameCol!==-1){nome=String(row[nameCol]||'').trim()}
        else{
          for(let c=0;c<=Math.min(5,row.length);c++){
            const v=String(row[c]||'').trim();
            if(v.length>3&&!/^\d+$/.test(v)&&!v.includes('Código')&&!v.includes('Razão')&&!v.includes('Inscrição')&&!v.includes('Competência')){
              nome=v;break;
            }
          }
        }
        if(!nome||nome.length<3){skipped++;continue}
        if(nome.includes('Código')||nome.includes('Razão')||nome.includes('Inscrição')||nome.includes('Competência')){skipped++;continue}
        const cargo=funcCol!==-1?String(row[funcCol]||'').trim():'';
        const local=localCol!==-1?String(row[localCol]||'').trim():'';
        const linha=lineCol!==-1?String(row[lineCol]||'').trim():'';
        const unidade=unitCol!==-1?String(row[unitCol]||'').trim():'';
        let admissao='';
        if(admCol!==-1){
          const rawVal=row[admCol];
          if(typeof rawVal==='number'&&rawVal>30000&&rawVal<50000){
            const dt=new Date((rawVal-25569)*86400*1000);
            admissao=dt.toLocaleDateString('pt-BR');
          }else{admissao=String(rawVal||'').trim()}
        }
        let turno='';
        if(turnoCol!==-1){turno=String(row[turnoCol]||'').trim()}
        else{
          for(let c=row.length-1;c>=Math.max(0,row.length-4);c--){
            const v=String(row[c]||'').trim().toUpperCase();
            if(v==='DIURNO'||v==='NOTURNO'||v.includes('NOTURNO')){
              turno=v;break;
            }
          }
        }
        const dept=local||'Operações';
        const exists=d.employees.find(x=>x.nome&&x.nome.toUpperCase()===nome.toUpperCase());
        if(exists){
          let changed=false;
          if(cargo&&!exists.cargo){exists.cargo=cargo;changed=true}
          if(linha&&!exists.linha){exists.linha=linha;changed=true}
          if(unidade&&!exists.unidade){exists.unidade=unidade;changed=true}
          if(admissao&&!exists.admissao){exists.admissao=admissao;changed=true}
          if(changed){updated++}
          skipped++;continue;
        }
        const emp={
          id:Date.now()+i,
          nome,
          cargo:cargo||'Não informado',
          cpf:'',
          dept,
          tel:'',
          email:'',
          nasc:'',
          obs:[turno?'Turno: '+turno:'',linha?'Linha: '+linha:'',unidade?'Unidade: '+unidade:'',admissao?'Admissão: '+admissao:''].filter(Boolean).join(' | '),
          avatar:nome.split(' ').filter(x=>x.length>1).map(x=>x[0]).join('').substring(0,2).toUpperCase(),
          photo:'',
          eq:0,
          status:'Ativo',
          linha,
          unidade,
          admissao
        };
        d.employees.push(emp);
        imported++;
      }
      d._lastUpdate=Date.now();
      d._dataCount=countData(d);
      localStorage.setItem(DB,JSON.stringify(d));
      fetchFB(FB_URL,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).catch(()=>{});
      addLog('import',`Importação Excel: ${imported} novos, ${updated} atualizados, ${skipped} ignorados`);
      renderAll();
      const parts=[`${imported} novos`];
      if(updated>0)parts.push(`${updated} atualizados`);
      if(skipped>0)parts.push(`${skipped} ignorados`);
      toast(`Importado! ${parts.join(', ')}`,'s');
    }catch(err){
      console.error('[Import] Erro:',err);
      toast('Erro ao ler planilha: '+err.message,'e');
    }
  };
  reader.readAsArrayBuffer(file);
  e.target.value='';
}

function filterEmployees(){
  const deptFilter=document.getElementById('empDeptFilter')?.value||'';
  if(deptFilter){
    document.querySelectorAll('#sec-funcionarios .tab').forEach(t=>t.classList.remove('active'));
    const tabs={Operações:'operacao',Administrativo:'Administrativo',Comercial:'Comercial',Logística:'operacao',Expedição:'operacao',Portaria:'operacao',Manutenção:'operacao',EPI:'operacao'};
    const tab=tabs[deptFilter];
    if(tab){document.querySelectorAll('#sec-funcionarios .emp-tab-content').forEach(c=>c.style.display='none');const el=document.getElementById('empTab-'+tab);if(el)el.style.display='block'}
    else{document.querySelectorAll('#sec-funcionarios .tab')[0]?.click()}
  }
  renderAll()
}

function checkQtyField(){const qf=document.getElementById('batchFields');const isLoteModal=document.getElementById('mtInv')?.textContent?.includes('Lote');if(isLoteModal){return}const t=document.getElementById('iType').value;const m=(document.getElementById('iModel').value||'').toLowerCase();const b=(document.getElementById('iBrand').value||'').toLowerCase();const p=(document.getElementById('iPat').value||'').toLowerCase();if(document.getElementById('iId').value!==''){qf.style.display='none';return}const isKbMouse=m.includes('teclado')||m.includes('keyboard')||m.includes('mouse')||b.includes('teclado')||b.includes('keyboard')||b.includes('mouse')||p.includes('teclado')||p.includes('keyboard')||p.includes('mouse');if(isKbMouse){qf.style.display='block';document.getElementById('iStatus').value='Estoque';document.getElementById('iPat').value='Gerando...';document.getElementById('iPat').disabled=true;updatePatPreview()}}

function updatePatPreview(){const qty=parseInt(document.getElementById('iQty').value)||1;if(qty<=1){document.getElementById('batchPreview').style.display='none';return}const d=getDB();const prefix='INT-'+new Date().getFullYear()+'-KB';let maxNum=0;d.inventory.forEach(x=>{if(x.pat&&x.pat.startsWith(prefix)){const n=parseInt(x.pat.replace(prefix,''));if(n>maxNum)maxNum=n}});const preview=[];for(let i=1;i<=Math.min(qty,10);i++){preview.push(prefix+String(maxNum+i).padStart(4,'0'))}const el=document.getElementById('batchPreview');el.style.display='block';el.innerHTML='<div style="margin-bottom:6px"><strong>Serão criados '+qty+' itens:</strong></div>'+preview.map(p=>'<span style="display:inline-block;padding:2px 8px;margin:2px;background:var(--acg);color:var(--ac);border-radius:4px;font-family:monospace;font-size:11px">'+p+'</span>').join('')+(qty>10?'<div style="margin-top:4px;color:var(--t3)">... e mais '+(qty-10)+' itens</div>':'')}

document.addEventListener('DOMContentLoaded',function(){const iType=document.getElementById('iType');const iModel=document.getElementById('iModel');const iBrand=document.getElementById('iBrand');const iPat=document.getElementById('iPat');if(iType)iType.addEventListener('change',checkQtyField);if(iModel)iModel.addEventListener('input',checkQtyField);if(iBrand)iBrand.addEventListener('input',checkQtyField);if(iPat)iPat.addEventListener('input',checkQtyField)})

document.addEventListener('DOMContentLoaded',function(){
  try{
    const yr=document.getElementById('loginYear');if(yr)yr.textContent=String(new Date().getFullYear());
    loadRememberedEmail();
    const np=document.getElementById('resetNewPass');if(np)np.addEventListener('input',function(){pwStrength(this.value)});
    const cn=document.getElementById('cfgPassNew');if(cn)cn.addEventListener('input',function(){pwStrength(this.value,'cfgPassMeter','cfgPassHint')});
    const em=document.getElementById('loginEmail');if(em)em.addEventListener('keydown',function(ev){if(ev.key==='Enter'){const pw=document.getElementById('loginPassword');if(pw&&!pw.value)ev.preventDefault()}});
    const mo=document.getElementById('modalResetPass');if(mo)mo.addEventListener('click',function(ev){if(ev.target===mo)closeModal('modalResetPass')});
  }catch(e){console.error('init login:',e)}
});

function saveInv(e){e.preventDefault();const d=getDB();const id=document.getElementById('iId').value;const showIMEI=['master','admin'].includes(user.profile);const qty=parseInt(document.getElementById('iQty')?.value)||1;const isBatch=qty>1&&!id;if(isBatch){const prefix='INT-'+new Date().getFullYear()+'-KB';let maxNum=0;d.inventory.forEach(x=>{if(x.pat&&x.pat.startsWith(prefix)){const n=parseInt(x.pat.replace(prefix,''));if(n>maxNum)maxNum=n}});const baseData={sn:document.getElementById('iSN').value||'',eq:document.getElementById('iType').value,mm:document.getElementById('iModel').value,brand:document.getElementById('iBrand').value,dept:document.getElementById('iDept').value,resp:document.getElementById('iResp').value,status:'Estoque',val:document.getElementById('iValBatch').value||document.getElementById('iVal').value,date:document.getElementById('iDate').value};let created=0;for(let i=0;i<qty;i++){const pat=prefix+String(maxNum+i+1).padStart(4,'0');const item={...baseData,id:Date.now()+i,pat,sn:baseData.sn||genSN()};if(showIMEI){item.imei1='';item.imei2='';item.serie='';item.chip='';item.linha='';item.acessorios=''}d.inventory.push(item);created++}d.Logs.unshift({id:Date.now(),time:new Date().toLocaleString('pt-BR'),user:user?.nome||'Sistema',action:'create',detail:`Patrimônio em lote: ${created}x ${baseData.eq} (${baseData.mm})`,ip:'192.168.1.'+Math.floor(Math.random()*255)});if(d.Logs.length>500)d.Logs=d.Logs.slice(0,500);setDB(d);closeModal('modalInv');renderAll();toast(created+' patrimônios cadastrados!','s');return}const data={pat:document.getElementById('iPat').value,sn:document.getElementById('iSN').value||genSN(),eq:document.getElementById('iType').value,mm:document.getElementById('iModel').value,brand:document.getElementById('iBrand').value,dept:document.getElementById('iDept').value,resp:document.getElementById('iResp').value,status:document.getElementById('iStatus').value,val:document.getElementById('iVal').value,date:document.getElementById('iDate').value};if(showIMEI){data.imei1=document.getElementById('iIMEI1').value;data.imei2=document.getElementById('iIMEI2').value;data.serie=document.getElementById('iSerie').value;data.chip=document.getElementById('iChip').value;data.linha=document.getElementById('iLinha').value;data.acessorios=document.getElementById('iAcessorios').value}if(!id){const dupPat=d.inventory.find(x=>x.pat&&x.pat.toUpperCase()===data.pat.toUpperCase());if(dupPat){toast('⚠️ Patrimônio já cadastrado: '+dupPat.pat+' ('+dupPat.eq+')','e');return}const dupSN=d.inventory.find(x=>x.sn&&x.sn.toUpperCase()===data.sn.toUpperCase());if(dupSN){toast('⚠️ SN já cadastrado: '+dupSN.sn+' ('+dupSN.eq+')','e');return}if(data.imei1){const dupIMEI=d.inventory.find(x=>x.imei1&&x.imei1===data.imei1);if(dupIMEI){toast('⚠️ IMEI já cadastrado: '+dupIMEI.imei1+' ('+dupIMEI.eq+')','e');return}}}if(id){const i=d.inventory.findIndex(x=>x.id==id);if(i!==-1){d.inventory[i]={...d.inventory[i],...data}}}else{data.id=Date.now();d.inventory.push(data)}d.Logs.unshift({id:Date.now(),time:new Date().toLocaleString('pt-BR'),user:user?.nome||'Sistema',action:id?'update':'create',detail:`Patrimônio: ${data.pat}`,ip:'192.168.1.'+Math.floor(Math.random()*255)});if(d.Logs.length>500)d.Logs=d.Logs.slice(0,500);setDB(d);closeModal('modalInv');renderAll();toast(id?'Atualizado!':'Cadastrado!','s')}

