function saveStk(e){e.preventDefault();const d=getDB();const id=document.getElementById('sId').value;const ent=parseInt(document.getElementById('sEnt').value)||0,sai=parseInt(document.getElementById('sSai').value)||0;const data={name:document.getElementById('sNome').value,cat:document.getElementById('sCat').value,ent,sai,saldo:ent-sai,status:ent-sai<=2?'Crítico':ent-sai<=5?'Baixo':'OK',icon:{Armazenamento:'📦',Componentes:'🧠',Periféricos:'🖱️',Cabos:'🔌',Adaptadores:'🔗'}[document.getElementById('sCat').value]||'📦'};if(!id){const dup=d.stock.find(x=>x.name&&x.name.toUpperCase()===data.name.toUpperCase()&&x.cat===data.cat);if(dup){toast('⚠️ Item já cadastrado: '+dup.name+' ('+dup.cat+')','e');return}}if(id){const i=d.stock.findIndex(x=>x.id==id);if(i!==-1){d.stock[i]={...d.stock[i],...data};addLog('update',`Item atualizado: ${data.name}`)}}else{data.id=Date.now();d.stock.push(data);addLog('create',`Novo item: ${data.name}`)}setDB(d);closeModal('modalStk');renderAll();toast(id?'Atualizado!':'Cadastrado!','s')}

