  const oiAllowed=uid?oiPermOf(uid):[];
  const oiUsers=qualPermUsers();
  const labelState={total:['Acesso total','var(--qd-green)'],parcial:['Acesso parcial','var(--qd-or)'],'sem-acesso':['Sem acesso','var(--d)'],'nao-configurado':['Não configurado','var(--t3)']};
