function indRenderAcesso(){
  return'<div class="grid g4" style="margin-bottom:20px">'
  +indKpi('Seu perfil','\uD83D\uDD11','',indIsQualDept()?'Setor Qualidade - liberado':'Liberado por permissao')
  +indKpi('Permissao indicadores',indCanAccess()?'\u2705':'\u274C',indCanAccess()?'o':'r','whitelist nominal')
  +indKpi('Acoes sensiveis','4','g','download / formula / log / acesso')
  +indKpi('Registros de auditoria',String((getDB().indAudit||[]).length),'p','ultimos 500')
  +'</div>'
  +'<div class="card" style="margin-bottom:20px"><div class="ct" style="margin-bottom:12px">\uD83D\uDD11 Solicitar token de acesso</div>'
  +'<p style="font-size:12px;color:var(--t3);margin-bottom:14px">Toda acao sensivel exige um token de uso unico, valido por 30 minutos. A T.I. recebe a solicitacao e emite o codigo.</p>'
  +'<div class="grid g4">'+Object.entries(IND_ACTIONS).map(([k,a])=>'<button class="qq-btn" style="padding:14px" onclick="indRequireToken(\''+k+'\',()=>indRequestToken(\''+k+'\'))">'+a.i+'<br><span style="font-size:11px">'+a.l+'</span></button>').join('')+'</div></div>'
  +'<div class="card" style="margin-bottom:20px"><div class="ct" style="margin-bottom:12px">\uD83D\uDCCB Log de auditoria</div><div id="indAuditList"></div></div>';}
function indRenderAccessPanel(){
  const box=document.getElementById('indAuditList');if(!box)return;
  const d=getDB();const adm=indIsAdmin();
  const reqs=(d.indRequests||[]).slice(-12).reverse();
  const toks=(d.indTokens||[]).slice(-12).reverse();
  const aud=(d.indAudit||[]).slice(0,40);
  box.innerHTML=(adm?'<div style="font-size:11px;color:var(--w);margin-bottom:10px">\uD83D\uDD11 Visao de TI/Master - voce pode emitir e revogar tokens.</div>':'')
  +(reqs.length?'<div class="ct" style="margin:10px 0 6px;font-size:13px">Solicitacoes</div>'+reqs.map(r=>'<div style="display:flex;gap:10px;align-items:center;padding:8px;border-bottom:1px solid var(--bd);font-size:12px"><div style="flex:1"><b>'+r.nome+'</b> <span style="color:var(--t3)">'+r.actionLabel+' - '+r.created+'</span></div>'
    +(r.status==='Pendente'&&adm?'<button class="qq-btn" onclick="indGenerateToken('+r.id+')">\uD83D\uDD11 Emitir</button>':(r.status==='Pendente'?'<span style="color:var(--w);font-size:11px">Pendente</span>':'<span style="color:var(--s);font-size:11px">'+(r.code||r.status)+'</span>'))+'</div>').join(''):'')
  +(toks.length?'<div class="ct" style="margin:14px 0 6px;font-size:13px">Tokens</div>'+toks.map(t=>'<div style="display:flex;gap:10px;align-items:center;padding:8px;border-bottom:1px solid var(--bd);font-size:12px"><div style="flex:1;font-family:\'JetBrains Mono\',monospace">'+t.code+' <span style="color:var(--t3);font-family:inherit">'+t.actionLabel+' - '+t.status+'</span></div>'+(adm&&t.status==='Ativo'?'<button class="qq-btn" onclick="indRevokeToken('+t.id+')">Revogar</button>':'')+'</div>').join(''):'')
  +'<div class="ct" style="margin:14px 0 6px;font-size:13px">Registros</div>'
  +(aud.length?aud.map(a=>'<div style="padding:6px 0;border-bottom:1px solid var(--bd);font-size:11px"><b style="color:var(--t2)">'+a.user+'</b> <span style="color:var(--t3)">'+(a.dept||'-')+' @ '+a.time+'</span><div>'+a.action+' - '+a.detail+'</div></div>').join(''):'<p style="color:var(--t3);font-size:12px">Sem registros</p>')
  +'<div style="margin-top:12px"><button class="qq-btn" onclick="indRequireToken(\'log\',indExportAudit)">\uD83D\uDCC4 Exportar log</button></div>';}

function indEditFormula(panel){
  const alvos=(panel?indFormulasOf(panel):IND_FORMULAS);
  const opts=panel?'':'<div class="fg" style="margin-bottom:12px"><label class="fl">Painel</label><select class="fi" id="indFPanel"><option value="">Todos</option><option value="sac">Dashboard SAC</option><option value="cont">Contencoes Internas</option><option value="recl">Indicador de Reclamacoes</option></select></div>';
  const h=alvos.map((f,i)=>'<div style="margin-bottom:10px"><label class="fl">'+f.l+'</label><textarea class="fi" id="indF'+i+'" rows="3" style="width:100%;font-family:\'JetBrains Mono\',monospace;font-size:11px">'+f.f.replace(/[<>&]/g,m=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[m]))+'</textarea></div>').join('');
  showConfirm('\uD83D\uDDEE Alterar formulas dos indicadores',opts+'<div style="max-height:52vh;overflow:auto;text-align:left">'+h+'</div>',()=>{
    const d=getDB();if(!d.indFormulas)d.indFormulas={};
    alvos.forEach((f,i)=>{const v=document.getElementById('indF'+i)?.value;if(v&&v!==f.f){d.indFormulas[f.k]={f:v,p:f.p};f.f=v}});
    setDB(d);try{pushToFirebase()}catch(e){}
    indAuditLog('formula_alterada',Object.keys(d.indFormulas).length+' formulas alteradas');
    toast('Formulas atualizadas e auditadas!','s');indRender()});
}
function indExportAudit(){const d=getDB();const rows=[['Data','Usuario','Setor','Perfil','Acao','Detalhe']];(d.indAudit||[]).forEach(a=>rows.push([a.time,a.user,a.dept,a.profile,a.action,a.detail]));indAuditLog('log_exportado','Log de auditoria exportado ('+(d.indAudit||[]).length+' registros)');indCsv('auditoria-indicadores',rows)}
function indExportXlsx(){indAuditLog('download','Exportacao Excel autorizada');const r=indFilterSac();const rows=[[IND_SCHEMA.sac.tabela].concat(IND_SCHEMA.sac.campos.map(c=>c.n))];r.forEach(x=>rows.push(IND_SCHEMA.sac.campos.map(c=>x[c.k])));try{if(window.XLSX){const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'OPEN ISSUES');XLSX.writeFile(wb,'indicadores_sac_'+indNow().toISOString().slice(0,10)+'.xlsx');return}}catch(e){}indCsv('indicadores_sac',rows)}
