/* Lista de permissões do REGISTRO DE NÃO CONFORMIDADES (OPEN ISSUES).
   O responsável libera campo a campo para cada usuário: quem não tem o campo
   liberado NÃO enxerga a coluna na tabela (informação oculta) e não consegue
   gravar nele no formulário. */
/* Campos CALCULADOS: nao sao preenchidos no formulario (sao deduzidos pelo
   sistema). Nao fazem sentido como permissao - aparecem sempre para todo
   mundo, senao o usuario perde a coluna sem poder liberar de novo. */
const OI_CALC_FIELDS=['leadTime'];
/* Campos que seguem a permissao de outro (o anexo da nota fiscal acompanha
   a nota fiscal - antes ficava sem permissao para NINGUEM e por isso o
   campo ficava escondido e o anexo nunca era gravado). */
const OI_PERM_ALIAS={nfAnexo:'notaFiscal'};
const OI_PERM_FIELDS=OI_COLS.filter(c=>c.k!=='__ac'&&OI_CALC_FIELDS.indexOf(c.k)<0).map(c=>({k:c.k,l:c.l}));
function oiPermAll(){return OI_PERM_FIELDS.map(f=>f.k)}
function oiPermOf(uid){
  if(uid==null||uid==='')return [];
  try{if(qualIsAdmin())return oiPermAll()}catch(e){}
  const d=getDB();const map=d.oiPerm||{};const arr=map[String(uid)];
  return Array.isArray(arr)?arr:[];
}
function oiFieldAllowed(k){const alvo=OI_PERM_ALIAS[k]||k;return oiPermOf(user&&user.id).indexOf(alvo)>=0}
function oiVisibleCols(){return OI_COLS.filter(c=>c.k==='__ac'?true:(OI_CALC_FIELDS.indexOf(c.k)>=0||oiFieldAllowed(c.k)))}
/* Migração única: usuários que já tinham acesso ao registro passam a enxergar
   todos os campos até o responsável restringir campo a campo. */
function oiMigratePerm(){
  const d=getDB();
  if(d.oiPermSeeded)return;
  d.oiPerm=d.oiPerm||{};
  (d.users||[]).forEach(u=>{
    if(!u)return;
    let temAcesso=false;
    try{temAcesso=(qualRoleOf(u)==='admin'||qualRoleOf(u)==='operador')}catch(e){}
    if(!temAcesso){try{temAcesso=hasUserPermission(u.id,'qualidade')}catch(e){}}
    if(!temAcesso){try{temAcesso=(u.dept==='Qualidade')}catch(e){}}
    if(temAcesso&&!d.oiPerm[String(u.id)])d.oiPerm[String(u.id)]=oiPermAll();
  });
  d.oiPermSeeded=true;
  setDB(d);try{pushToFirebase()}catch(e){}
}
function oiParseNum(v){
  if(v==null||v==='')return '';
  let t=String(v).replace(/[^\d.,-]/g,'');
  if(!t)return '';
  const lastC=t.lastIndexOf(','),lastD=t.lastIndexOf('.');
  if(lastC>lastD)t=t.replace(/\./g,'').replace(',','.');
  else if(lastD>lastC&&lastC>=0)t=t.replace(/,/g,'');
  else if(t.indexOf(',')>=0)t=t.replace(',','.');
  const n=parseFloat(t);
  return isFinite(n)?n:'';
}
function oiNumBR(v){const n=(typeof v==='number')?v:oiParseNum(v);if(n===''||n==null)return '-';return n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function oiMoneyBR(v){const n=(typeof v==='number')?v:oiParseNum(v);if(n===''||n==null)return '-';return 'R$ '+n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function oiLeadDays(ab,fech){
  if(!ab||!fech)return '';
  const a=new Date(String(ab).slice(0,10)+'T00:00:00'),b=new Date(String(fech).slice(0,10)+'T00:00:00');
  if(isNaN(a)||isNaN(b))return '';
  return Math.max(0,Math.round((b-a)/86400000));
}
/* Status automático:
   - "Pendente": o registro está aguardando o preenchimento interno
     (Causa raiz + Prazo de ação). Só a equipe interna tira do Pendente.
   - "Concluído": data de fechamento informada.
   - "Em Atraso": prazo vencido.
   - "Em Aberto": análise interna concluída e dentro do prazo. */
function oiAutoStatus(rec){
  if(rec.status==='Sem Plano de Ação')return 'Sem Plano de Ação';
  if(rec.dataFechamento)return 'Concluído';
  if(rec.status==='Concluído')return 'Concluído';
  const temAnalise=!!(rec.causaRaiz&&rec.planoAcao);
  if(!temAnalise&&!rec.statusManual)return 'Pendente';
  if(rec.prazo){
    const p=new Date(String(rec.prazo).slice(0,10)+'T23:59:59');
    if(!isNaN(p)&&p<Date.now())return 'Em Atraso';
  }
  return 'Em Aberto';
}
let oiReady=false;
function oiEl(id){try{return document.getElementById(id)}catch(e){return null}}
function oiEsc(x){return String(x==null?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function oiToday(){const d=new Date();const p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())}
function oiNewId(){return 'oi-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function oiNextNAb(){let max=0;oiDB().forEach(r=>{if(/^\d+$/.test(String(r.nAb||'')))max=Math.max(max,parseInt(r.nAb,10))});return String(max+1).padStart(3,'0')}
function oiDB(){const d=getDB();if(!Array.isArray(d.openIssues))d.openIssues=[];return d.openIssues}
function oiPut(list){const d=getDB();d.openIssues=list;setDB(d);try{pushToFirebase()}catch(e){}}
function oiFill(id,opts,label){
  const e=oiEl(id);if(!e)return;
  e.innerHTML='<option value="">'+oiEsc(label)+'</option>'+opts.map(o=>'<option>'+oiEsc(o)+'</option>').join('');
}
/* ===== CONTENCOES INTERNAS =====
   Area do funcionario: material contido, retrabalhos internos e analise
   de camadas. Cada tipo de lancamento tem a SUA collection e a SUA aba.
   Tudo o que e lancado aqui alimenta o Dashboard e os Indicadores. */
const CONT_COLS={lancamentos:'contencoes',retrabalho:'retrabalhos',camadas:'analiseCamadas'};
const CONT_MATERIAIS=['Tubo C/Base','Bases','Tubos','Cantoneiras','Braco','Cantoneira','Piso','Grades','Base/Poste','Outro'];
const CONT_TIPOS=['Falhas de galvanizacao','Pecas queimadas','Amassamento','Excessos de zinco','Impurezas do banho','Outro caso (nao esta em nenhuma destas)'];
/* Quem pode ACESSAR a area: a T.I. e a Qualidade sempre; os demais
   somente com a permissao nominal `contencoes` (liberada pelo master
   na tela de Permissoes). */
function contPodeAcessar(){
  try{
    if(!user)return false;
    if(!['master','admin','gestor_ti','tecnico'].includes(user.profile))return false;
    return true;
  }catch(e){return false}
}
function contPodeVer(){
  try{
    if(!user)return false;
    if(['master','admin','gestor_ti','tecnico'].includes(user.profile))return true;
    if(user.dept==='Qualidade')return true;
    try{if(qualIsAdmin&&qualIsAdmin())return true}catch(e){}
    return !!hasUserPermission(user.id,'contencoes');
  }catch(e){return false}
}
/* Edicao direta (alterar registro ja existente) e restrita a quem o
   servidor tambem autoriza: T.I. e Qualidade. Quem tem apenas a permissao
   nominal `contencoes` continua podendo SOMENTE acrescentar lancamentos. */
function contPodeEditar(){
  try{
    if(!contPodeVer())return false;
    if(['master','admin','gestor_ti','tecnico'].includes(user.profile))return true;
    if(user.dept==='Qualidade'||user.dept==='Tecnologia')return true;
    try{if(qualIsAdmin&&qualIsAdmin())return true}catch(e){}
    return false;
  }catch(e){return false}
}
function contDataHora(v){
  try{
    if(v===null||v===undefined||v==='')return '-';
    if(typeof v==='number'||/^\d{10,}$/.test(String(v))){
      const d=new Date(Number(v));if(!isNaN(d))return d.toLocaleString('pt-BR');
    }
    return String(v);
  }catch(e){return '-'}
}
function contDiffCampos(antes,depois){
  const out=[];
  Object.keys(depois||{}).forEach(k=>{
    if(k==='_updatedAt')return;
    const a=antes?antes[k]:undefined,b=depois[k];
    if(String(a==null?'':a)!==String(b==null?'':b))out.push(k);
  });
  return out;
}
function contRegistrarEdicao(rec,antes,rotulo){
  try{
    const agora=Date.now();
    const ed={
      por:(user&&user.nome)||'Sistema',
      userId:(user&&user.id)||null,
      em:agora,
      emTexto:new Date(agora).toLocaleString('pt-BR'),
      campos:contDiffCampos(antes,rec)
    };
    rec.atualizadoPor=ed.por;
    rec.atualizadoEm=agora;
    rec.edicoes=(Array.isArray(antes&&antes.edicoes)?antes.edicoes:[]).slice(-19).concat([ed]);
    rec._updatedAt=agora;
    try{indAuditLog(rotulo+'_editada','Registro editado por '+ed.por+' | '+(rec.cliente||'')+' | campos: '+(ed.campos.join(', ')||'-'))}catch(e){}
  }catch(e){}
}
function contResetEditUI(tipo){
  try{
    const m={ret:{id:'ret',info:'retEditInfo',cancel:'retCancelEditBtn',btn:'retSubmitBtn',label:'&#128257; Lan&ccedil;ar retrabalho'},
      cam:{id:'cam',info:'camEditInfo',cancel:'camCancelEditBtn',btn:'camSubmitBtn',label:'&#129514; Salvar an&aacute;lise'}}[tipo||'']||{id:'cont',info:'contEditInfo',cancel:'contCancelEditBtn',btn:'contSubmitBtn',label:'&#128230; Lan&ccedil;ar conten&ccedil;&atilde;o'};
    if(m.id==='ret')retEditId=null;else if(m.id==='cam')camEditId=null;else contEditId=null;
    const info=document.getElementById(m.info);if(info)info.style.display='none';
    const cancel=document.getElementById(m.cancel);if(cancel)cancel.style.display='none';
    const btn=document.getElementById(m.btn);if(btn)btn.innerHTML=m.label;
  }catch(e){}
}
function contMostrarEditInfo(tipo,rec){
  try{
    const m={ret:{info:'retEditInfo',cancel:'retCancelEditBtn',btn:'retSubmitBtn'},
      cam:{info:'camEditInfo',cancel:'camCancelEditBtn',btn:'camSubmitBtn'}}[tipo||'']||{info:'contEditInfo',cancel:'contCancelEditBtn',btn:'contSubmitBtn'};
    const info=document.getElementById(m.info);
    const cancel=document.getElementById(m.cancel);
    const btn=document.getElementById(m.btn);
    if(info){
      info.style.display='';
      info.innerHTML='&#9998; Editando registro de <b>'+oiEsc(rec.cliente||'-')+'</b>'
        +' · lan&ccedil;ado por <b>'+oiEsc(rec.criadoPor||'-')+'</b> em <b>'+contDataHora(rec.criadoEm)+'</b>.'
        +' A altera&ccedil;&atilde;o ser&aacute; registrada com seu usu&aacute;rio, data e hora.';
    }
    if(cancel)cancel.style.display='';
    if(btn)btn.innerHTML='&#128190; Salvar altera&ccedil;&otilde;es';
  }catch(e){}
}
/* O resultado "Visual" da analise de camadas e informacao sensivel:
   fica oculto para quem tem apenas a permissao de lancamento. A Qualidade,
   a T.I. e quem receber a permissao nominal `analiseVisual` enxergam. */
function camPodeVerVisual(){
  try{
    if(!contPodeVer())return false;
    if(['master','admin','gestor_ti','tecnico'].includes(user.profile))return true;
    if(user.dept==='Qualidade'||user.dept==='Tecnologia')return true;
    try{if(qualIsAdmin&&qualIsAdmin())return true}catch(e){}
    return !!hasUserPermission(user.id,'analiseVisual');
  }catch(e){return false}
}
function contSetMaterial(selId,txtId,valor){
  try{
    const sel=document.getElementById(selId),txt=document.getElementById(txtId);
    const v=String(valor||'').trim();
    if(!sel)return;
    const existe=Array.from(sel.options).some(o=>o.value===v);
    if(v&&existe){sel.value=v;if(txt)txt.value='';}
    else if(v){sel.value='Outro';if(txt)txt.value=v;}
    else{sel.value='';if(txt)txt.value='';}
    if(selId==='contMaterial')contMaterialOnChange();else retMaterialOnChange();
  }catch(e){}
}
function contMesDaData(d){try{const dt=new Date(String(d||'').slice(0,10)+'T00:00:00');if(isNaN(dt))return '';return QUAL_MESES_ORDER[dt.getMonth()]}catch(e){return ''}}
function contAnoDaData(d){try{const dt=new Date(String(d||'').slice(0,10)+'T00:00:00');if(isNaN(dt))return '';return String(dt.getFullYear())}catch(e){return ''}}
/* Quando existe um codigo de falha que corresponde, o campo "Modo de
   falha" do lancamento tambem e preenchido (os indicadores usam ele). */
function contModoFalha(tipo){try{const f=(typeof OI_FALHAS!=='undefined'&&OI_FALHAS)||[];if(tipo==='Amassamento')return f.find(x=>/^F20 /.test(x))||'';if(tipo==='Excessos de zinco')return f.find(x=>/^F15 /.test(x))||'';if(tipo==='Impurezas do banho')return f.find(x=>/^F9 /.test(x))||'';return ''}catch(e){return ''}}
function contNum(v){try{return parseFloat(String(v==null?'':v).replace(/[^\d,.-]/g,'').replace(/\./g,'').replace(',','.'))||0}catch(e){return 0}}
function contPreencheMes(){try{const d=document.getElementById('contData');const m=document.getElementById('contMes');if(d&&m&&d.value&&!m.value)m.value=contMesDaData(d.value)}catch(e){}}
function contLimpar(){try{contResetEditUI('cont');['contData','contCliente','contRomaneio','contTipo','contKg','contDescricao','contMotivo','contTurno','contMaterial','contMaterialOutro','contInfLideranca','contInfSistema'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});const m=document.getElementById('contMes');if(m)m.value='';const d=document.getElementById('contData');if(d)d.value=oiToday();contMaterialOnChange()}catch(e){}}
function contDB(col){const d=getDB();const c=col||'contencoes';if(!Array.isArray(d[c]))d[c]=[];return d[c]}
function contPut(col,list){const d=getDB();d[col]=list;setDB(d);try{pushToFirebase()}catch(e){}}
function contFillMateriais(){
  try{
    [['contMaterial','contMaterialOutro'],['retMaterial','retMaterialOutro']].forEach(par=>{
      const sel=document.getElementById(par[0]);if(!sel)return;
      const cur=sel.value;
      sel.innerHTML='<option value="">-</option>'+CONT_MATERIAIS.map(m=>'<option value="'+oiEsc(m)+'">'+oiEsc(m)+'</option>').join('');
      if(cur)sel.value=cur;
    });
    contMaterialOnChange();retMaterialOnChange();
  }catch(e){}
}
function contMaterialOnChange(){try{const s=document.getElementById('contMaterial');const o=document.getElementById('contMaterialOutro');if(!s||!o)return;o.style.display=(s.value==='Outro')?'':'none'}catch(e){}}
function retMaterialOnChange(){try{const s=document.getElementById('retMaterial');const o=document.getElementById('retMaterialOutro');if(!s||!o)return;o.style.display=(s.value==='Outro')?'':'none'}catch(e){}}
function contMaterialEfetivo(selId,txtId){
  try{
    const s=String((document.getElementById(selId)||{}).value||'').trim();
    const t=String((document.getElementById(txtId)||{}).value||'').trim();
    if(s==='Outro')return t||'Outro';
    return s;
  }catch(e){return ''}
}
/* Migracao do legado: os lancamentos que ainda estavam no Open Issues
   (marcados com `origemContencao`) vao para a collection `contencoes`.
   O Open Issues passa a receber so SAC e Plano de Acao. */
function contMigrarLegado(){
  try{
    const d=getDB();
    const oi=Array.isArray(d.openIssues)?d.openIssues:[];
    const legado=oi.filter(r=>r&&r.origemContencao===1);
    if(!legado.length)return 0;
    const cont=Array.isArray(d.contencoes)?d.contencoes.slice():[];
    const ids=new Set(cont.map(r=>String(r&&r.id)));
    legado.forEach(r=>{if(!ids.has(String(r.id)))cont.push(r)});
    d.contencoes=cont;
    d.openIssues=oi.filter(r=>!(r&&r.origemContencao===1));
    legado.forEach(r=>{try{addDeletedId(d,r.id,'openIssues')}catch(e){}});
    setDB(d);
    try{pushToFirebase()}catch(e){}
    return legado.length;
  }catch(e){return 0}
}
let contTab='lancamentos';
let contEditId=null;
let retEditId=null;
function contNavigate(pg){
  try{
    if(!contPodeVer()){toast('Sem permissao para Contencoes Internas','e');return}
    if(!CONT_COLS[pg])return;
    contTab=pg;
    try{document.querySelectorAll('#contMainNav button').forEach(b=>b.classList.toggle('active',b.dataset.pg===pg))}catch(e){}
    try{document.querySelectorAll('#sec-contencoes .qq-tabpage').forEach(x=>x.classList.remove('active'))}catch(e){}
    const el=document.getElementById('contPage-'+pg);if(el)el.classList.add('active');
    renderContencoes();
  }catch(e){console.error('contNavigate',e)}
}
function contOpen(){
  try{
    if(!contPodeVer())return;
    contNavigate(contTab||'lancamentos');
  }catch(e){}
}
function renderContencoes(){
  try{
    contMigrarLegado();
    contFillMateriais();
    if(contTab==='retrabalho')renderRetrabalhos();
    else if(contTab==='camadas')renderCamadas();
    else renderContLancamentos();
  }catch(e){console.error('renderContencoes',e)}
}
function contEditar(id){
  try{
    if(!contPodeEditar()){toast('Sem permissao para editar lancamentos','e');return}
    const rec=contDB('contencoes').find(r=>String(r.id)===String(id));
    if(!rec){toast('Lancamento nao encontrado','e');return}
    contFillMateriais();
    contEditId=String(id);
    const E=(x)=>document.getElementById(x);
    if(E('contData'))E('contData').value=String(rec.dataAbertura||'').slice(0,10);
    if(E('contMes'))E('contMes').value=rec.mes||'';
    if(E('contTurno'))E('contTurno').value=rec.turno||'';
    if(E('contCliente'))E('contCliente').value=rec.cliente||'';
    if(E('contRomaneio'))E('contRomaneio').value=rec.romaneio||'';
    if(E('contTipo'))E('contTipo').value=rec.tipoContencao||'';
    if(E('contKg'))E('contKg').value=rec.contencaoKg!=null?String(rec.contencaoKg).replace('.',','):'';
    if(E('contInfLideranca'))E('contInfLideranca').value=rec.informadoLideranca||'';
    if(E('contInfSistema'))E('contInfSistema').value=rec.informadoSistema||'';
    if(E('contDescricao'))E('contDescricao').value=rec.descricao||'';
    if(E('contMotivo'))E('contMotivo').value=rec.motivo||'';
    contSetMaterial('contMaterial','contMaterialOutro',rec.material);
    contMostrarEditInfo('cont',rec);
    try{document.querySelector('#contPage-lancamentos form')?.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){}
  }catch(e){console.error('contEditar',e)}
}
function contCancelarEdicao(){
  contLimpar();
  toast('Edicao cancelada','i');
}
function contSalvar(ev){
  if(ev&&ev.preventDefault)ev.preventDefault();
  if(!contPodeVer()){toast('Sem permissao para lancar contencoes','e');return}
  const E=(id)=>document.getElementById(id);
  const data=String((E('contData')||{}).value||'').slice(0,10);
  const mes=(E('contMes')||{}).value||'';
  const cliente=String((E('contCliente')||{}).value||'').trim();
  const romaneio=String((E('contRomaneio')||{}).value||'').trim();
  const turno=(E('contTurno')||{}).value||'';
  const descricao=String((E('contDescricao')||{}).value||'').trim();
  const motivo=String((E('contMotivo')||{}).value||'').trim();
  const tipo=(E('contTipo')||{}).value||'';
  const kg=contNum((E('contKg')||{}).value);
  const material=contMaterialEfetivo('contMaterial','contMaterialOutro');
  const informadoLideranca=(E('contInfLideranca')||{}).value||'';
  const informadoSistema=(E('contInfSistema')||{}).value||'';
  if(!data){toast('Informe a data da contencao','e');return}
  if(!cliente){toast('Informe o cliente / fornecedor','e');return}
  if(!descricao){toast('Informe a descricao da peca','e');return}
  if(!tipo){toast('Informe o tipo de contencao','e');return}
  const dados={
    dataAbertura:data,
    mes:mes||contMesDaData(data),
    ano:contAnoDaData(data),
    dia:parseInt(data.slice(8,10),10)||0,
    cliente:cliente,
    romaneio:romaneio,
    turno:turno,
    material:material,
    descricao:descricao,
    motivo:motivo,
    tipoContencao:tipo,
    contencaoKg:kg,
    modoFalha:contModoFalha(tipo),
    informadoLideranca:informadoLideranca,
    informadoSistema:informadoSistema
  };
  const list=contDB('contencoes');
  if(contEditId){
    if(!contPodeEditar()){toast('Sem permissao para editar lancamentos','e');return}
    const idx=list.findIndex(r=>String(r.id)===String(contEditId));
    if(idx<0){toast('Lancamento nao encontrado','e');contLimpar();return}
    const antes=list[idx];
    const rec=Object.assign({},antes,dados);
    contRegistrarEdicao(rec,antes,'contencao');
    list[idx]=rec;
    contPut('contencoes',list.slice());
    contLimpar();
    renderContencoes();
    try{renderDashContencoes(getDB())}catch(e){}
    toast('Contencao atualizada. A edicao foi registrada com usuario, data e hora.','s');
    return;
  }
  const rec=Object.assign({
    id:oiNewId(),
    origemContencao:1,
    status:'Pendente',
    statusManual:0,
    _updatedAt:Date.now(),
    criadoPor:(user&&user.nome)||'',
    criadoEm:Date.now()
  },dados);
  list.push(rec);
  contPut('contencoes',list.slice());
  try{indAuditLog('contencao_interna','Contencao interna: '+cliente+' | '+tipo+' | '+kg+' kg')}catch(e){}
  contLimpar();
  renderContencoes();
  try{renderDashContencoes(getDB())}catch(e){}
  toast('Contencao lancada! O registro foi para as Contencoes Internas e para o Dashboard.','s');
}
/* Exclui um lancamento: SEMPRE com a senha master (validada no servidor).
   O navegador sozinho nao apaga nada - quem apaga e a T.I. */
async function contExcluir(id,colecao){
  try{
    if(!contPodeVer()){toast('Sem permissao','e');return}
    const col=colecao||'contencoes';
    const rec=contDB(col).find(r=>String(r.id)===String(id));
    if(!rec){toast('Lancamento nao encontrado','e');return}
    const pw=prompt('🗑️ Excluir lancamento\n\nEsta acao e exclusiva da T.I. e exige a SENHA MASTER.\n\nDigite a senha master para confirmar:');
    if(!pw){toast('Operacao cancelada','i');return}
    const r=await apiCall('/api/admin?op=registro-delete',{method:'POST',body:{colecao:col,id:String(id),senha:pw}});
    if(!(r&&r.ok)){toast('Nao foi possivel excluir o lancamento','e');return}
    const d=getDB();
    d[col]=(d[col]||[]).filter(x=>String(x.id)!==String(id));
    try{addDeletedId(d,id,col)}catch(e){}
    setDB(d);
    try{pushToFirebase()}catch(e){}
    try{indAuditLog('contencao_excluida','Lancamento excluido pela T.I.: '+col+'/'+id)}catch(e){}
    renderContencoes();
    try{renderDashContencoes(getDB())}catch(e){}
    toast('Lancamento excluido.','w');
  }catch(err){
    toast((err&&err.message)||'Nao foi possivel excluir o lancamento','e');
  }
}
