function fmtQual(n){if(n>=1000000)return(n/1000000).toFixed(1)+'M';if(n>=1000)return(n/1000).toFixed(1)+'K';return String(n)}
const qualPctPlugin={id:'qualPct',afterDatasetsDraw(chart,args,opts){const ctx=chart.ctx;const type=chart.config.type;if(type==='doughnut'||type==='pie'){const meta=chart.getDatasetMeta(0);const ds=chart.data.datasets[0];const vals=(ds.data||[]).map(x=>x||0);const total=vals.reduce((a,b)=>a+b,0);if(!total||!meta.data||!meta.data.length)return;ctx.save();ctx.font='bold 11px Arial';meta.data.forEach((arcEl,i)=>{const val=vals[i];const pct=Math.round((val/total)*100);if(pct<5||!arcEl||typeof arcEl.startAngle!=='number')return;const cs=ds.backgroundColor;ctx.fillStyle=qualInk(Array.isArray(cs)?cs[i%cs.length]:cs);const ang=(arcEl.startAngle+arcEl.endAngle)/2;const rad=(arcEl.innerRadius+arcEl.outerRadius)/2;const tx=arcEl.x+Math.cos(ang)*rad;const ty=arcEl.y+Math.sin(ang)*rad;let rot=ang*180/Math.PI;if(rot>90||rot<-90)rot+=180;ctx.save();ctx.translate(tx,ty);ctx.rotate(rot*Math.PI/180);ctx.textAlign='center';ctx.textBaseline='middle';const lb=pct+'%';ctx.strokeStyle=GALVA.white;ctx.lineWidth=2;ctx.lineJoin='round';ctx.strokeText(lb,0,0);ctx.fillText(lb,0,0);ctx.restore()});ctx.restore()}else if(type==='bar'){chart.data.datasets.forEach((ds,di)=>{const vals=(ds.data||[]).map(x=>x||0);const total=vals.reduce((a,b)=>a+b,0);if(!total)return;const meta=chart.getDatasetMeta(di);const mx=Math.max.apply(null,vals);const mi=vals.indexOf(mx);const el=(meta.data||[])[mi];if(!el)return;const pos=el.tooltipPosition?el.tooltipPosition():el.getCenterPoint?el.getCenterPoint():null;if(!pos)return;const pct=Math.round((mx/total)*100);if(pct<5)return;ctx.save();ctx.fillStyle=GALVA.white;ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillText(mx+'  '+pct+'%',pos.x,pos.y-3);ctx.restore()})}}};if(window.Chart)Chart.register(qualPctPlugin);
