async function fetchFB(url,opts={}){
  /* ANTES: chamava firebaseio.com direto, sem autenticacao - o banco era
     publico para leitura e escrita. AGORA: tudo passa pelo proxy, que
     valida a sessao e aplica a autorizacao no servidor. */
  const t=apiPathFor(url);
  const target=API_DATA+'?root='+encodeURIComponent(t.root)+'&path='+encodeURIComponent(t.path);
  const headers=apiHeaders(opts.headers);
  try{
    /* Um passo assincrono antes do fetch (o fluxo antigo aguardava o token
       do Firebase). Mantem a ordem das operacoes de sincronismo. */
    await Promise.resolve();
    const res=await fetch(target,{...opts,headers});
    let env=null;
    try{
      env=(typeof res.clone==='function')?await res.clone().json():await res.json();
    }catch(e){}
    if(!res.ok){
      const err=new Error((env&&env.message)||('Erro '+(res.status||'de rede')));
      err.status=res.status;err.code=(env&&(env.code||env.error))||'';
      /* 401 = sessao expirada/invalida. Sem isto o app continuava
         consultando a API a cada 5s (spam de 401 no console) e o
         usuario ficava numa tela quebrada sem saber o que fazer. */
      /* 401 = sessao expirada/invalida. Sem isto o app continuava
         consultando a API a cada 5s (spam de 401 no console) e o
         usuario ficava numa tela quebrada sem saber o que fazer. */
      if(res.status===401&&typeof expirarSessao==='function'){try{expirarSessao()}catch(e){}}
      throw err;
    }
    /* O proxy responde {ok:true,data:<valor>}. Desembrulha para o
       chamador receber o VALOR CRU, como a API do Firebase devolvia.
       Sem isso o sync via "Firebase vazio" e o app NUNCA carregava os
       dados do servidor - a tela ficava vazia apos limpar o cache. */
    const bruto=(env&&typeof env==='object'&&Object.prototype.hasOwnProperty.call(env,'data'))?env.data:env;
    return {
      ok:true,
      status:res.status,
      headers:res.headers,
      json:async()=>bruto,
      text:async()=>JSON.stringify(bruto)
    };
  }catch(e){
    return {ok:false,status:(e&&e.status)||0,json:async()=>({error:(e&&e.message)||'Falha de rede'}),text:async()=>String((e&&e.message)||'Falha de rede')};
  }
}

