function addScannedToInventory(code){
  const d=getDB();
  const newPat=`PAT-${new Date().getFullYear()}-${String(d.inventory.length+1).padStart(4,'0')}`;
  d.inventory.push({
    id:Date.now(),
    pat:newPat,
    sn:code,
    eq:'Não especificado',
    mm:'Não especificado',
    dept:'Tecnologia',
    resp:'',
    status:'Estoque',
    val:'',
    imei1:code.length===15?code:'',
    imei2:'',
    serie:'',
    chip:'',
    linha:'',
    acessorios:''
  });
  d.Logs.unshift({id:Date.now(),time:new Date().toLocaleString('pt-BR'),user:user?.nome||'Sistema',action:'create',detail:`Scanner: ${code} → ${newPat}`,ip:'192.168.1.'+Math.floor(Math.random()*255)});
  if(d.Logs.length>500)d.Logs=d.Logs.slice(0,500);
  setDB(d);
  toast(`Cadastrado: ${newPat}`,'s');
  document.getElementById('scannerResult').style.display='none';
  renderAll();
}

function addScannedToStock(code){
  const d=getDB();
  d.stock.push({
    id:Date.now(),
    icon:'📦',
    name:`Item ${code}`,
    cat:'Peça',
    ent:1,
    sai:0,
    saldo:1,
    status:'OK'
  });
  setDB(d);
  toast('Adicionado ao Estoque!','s');
  addLog('scanner',`Código escaneado → Estoque: ${code}`);
  document.getElementById('scannerResult').style.display='none';
  renderAll();
}

