function openTermoNotebook(){
  const d=getDB();
  const emps=(d.employees||[]).filter(x=>x.status!=='Desligado');
  const dl=document.getElementById('tnNomeList');
  if(dl){dl.innerHTML=emps.map(x=>'<option value="'+s(x.nome)+'">'+s(x.nome)+' - '+s(x.dept||'')+'</option>').join('')}
  const tnData=document.getElementById('tnData');
  if(tnData)tnData.value=new Date().toISOString().split('T')[0];
  showSec('termo-note');
  window._lastTermSec='termos';
  const fileInput=document.getElementById('tnArquivo');
  if(fileInput){fileInput.value='';fileInput.onchange=function(){previewTermoNoteFile(this)}}
  updateTermoNotePreview();
}

function previewTermoNoteFile(input){
  const el=document.getElementById('tnArquivoPreview');
  if(!el)return;
  if(!input.files||!input.files[0]){el.innerHTML='';return}
  const f=input.files[0];
  if(f.type==='application/pdf'){
    el.innerHTML='<div style="background:rgba(59,130,246,.1);border:1px solid rgba(59,130,246,.3);border-radius:8px;padding:12px;display:flex;align-items:center;gap:10px"><span style="font-size:24px">📄</span><div><div style="font-weight:600">'+s(f.name)+'</div><div style="font-size:11px;color:var(--t3)">'+(f.size/1024).toFixed(1)+' KB</div></div></div>';
  } else {
    const reader=new FileReader();
    reader.onload=function(e){el.innerHTML='<img src="'+e.target.result+'" style="max-width:100%;max-height:200px;border-radius:8px;border:1px solid var(--bd)">'};
    reader.readAsDataURL(f);
  }
}

function termoNoteGetVals(){
  return {
    nome:document.getElementById('tnNome')?.value||'',
    data:document.getElementById('tnData')?.value||'',
    fabricante:document.getElementById('tnFabricante')?.value||'',
    modelo:document.getElementById('tnModelo')?.value||'',
    patrimonio:document.getElementById('tnPatrimonio')?.value||'',
    serial:document.getElementById('tnSerial')?.value||'',
    processador:document.getElementById('tnProcessador')?.value||'',
    ram:document.getElementById('tnRam')?.value||'',
    armazenamento:document.getElementById('tnArmazenamento')?.value||'',
    tela:document.getElementById('tnTela')?.value||'',
    so:document.getElementById('tnSO')?.value||'',
    itens:(document.getElementById('tnItens')?.value||'').split('\n').filter(x=>x.trim()),
    cargo:document.getElementById('tnCargo')?.value||'',
    depto:document.getElementById('tnDepto')?.value||''
  };
}

function termoNoteGetEmp(nome){
  const d=getDB();
  return (d.employees||[]).find(x=>x.nome===nome)||null;
}

function termoNoteFormatDate(dateStr){
  if(!dateStr)return '____ de ________________________ de ________';
  const dt=new Date(dateStr+'T12:00:00');
  const meses=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
  return dt.getDate()+' de '+meses[dt.getMonth()]+' de '+dt.getFullYear();
}

