function saveTermoNoteAssinado(){
  const fileInput=document.getElementById('tnArquivo');
  const nome=document.getElementById('tnNome')?.value;
  if(!nome){toast('Selecione o funcionário','e');return}
  if(!fileInput||!fileInput.files||!fileInput.files[0]){toast('Envie o PDF ou imagem assinada','e');return}
  const f=fileInput.files[0];
  const reader=new FileReader();
  reader.onload=function(e){
    const d=getDB();
    if(!d.termosNote)d.termosNote=[];
    const v=termoNoteGetVals();
    const termo={id:Date.now(),funcionario:nome,data:v.data,fabricante:v.fabricante,modelo:v.modelo,patrimonio:v.patrimonio,serial:v.serial,processador:v.processador,ram:v.ram,armazenamento:v.armazenamento,tela:v.tela,so:v.so,itens:v.itens.join('\n'),arquivoNome:f.name,arquivoTipo:f.type,arquivoBase64:e.target.result,salvoEm:new Date().toLocaleString('pt-BR'),salvoPor:user?user.nome:'Sistema'};
    d.termosNote.push(termo);
    setDB(d);
    pushToFirebase();
    toast('Termo de notebook salvo com sucesso!','s');
    addLog('termo_notebook','Termo salvo: '+nome+' ('+f.name+')');
    fileInput.value='';
    document.getElementById('tnArquivoPreview').innerHTML='';
  };
  reader.readAsDataURL(f);
}

function renderTermosNote(){
  const d=getDB();
  const tb=document.getElementById('termosNoteTable');
  if(!tb)return;
  const termos=(d.termosNote||[]).slice().reverse();
  if(termos.length===0){tb.innerHTML='<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--t3)">Nenhum termo de notebook salvo</td></tr>';return}
  tb.innerHTML=termos.map(t=>'<tr style="border-bottom:1px solid var(--bd)"><td style="padding:8px;font-size:12px">'+(t.data||'-')+'</td><td style="padding:8px">'+s(t.funcionario)+'</td><td style="padding:8px">'+s(t.fabricante)+' '+s(t.modelo)+'</td><td style="padding:8px"><a href="'+(t.arquivoBase64||'#')+'" download="'+s(t.arquivoNome||'termo')+'" style="color:var(--ac);text-decoration:underline;font-size:12px">'+s(t.arquivoNome||'arquivo')+'</a></td><td style="padding:8px;font-size:11px;color:var(--t3)">'+s(t.salvoPor||'-')+'</td></tr>').join('');
}

function renderSignedTerms(){
  var tb=document.getElementById('signedTermsTable');
  if(!tb)return;
  var d=getDB();
  var links=(d.signLinks||[]).filter(function(x){return x.assinado}).slice().reverse();
  var badge=document.getElementById('signedCountBadge');
  if(badge)badge.textContent=links.length+' assinado(s)';
  if(links.length===0){tb.innerHTML='<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--t3)">Nenhum termo assinado digitalmente ainda</td></tr>';}else{
  tb.innerHTML=links.map(function(l){
    var tipo=l.tipo==='celular'?'📱 Celular':'💻 Notebook';
    var equip=l.tipo==='celular'?(l.fabricante||'')+' '+(l.modelo||''):(l.fabricante||'')+' '+(l.modelo||'');
    var tipoBadge=l.tipo==='celular'?'<span style="background:rgba(232,97,26,.15);color:#E8611A;padding:2px 8px;border-radius:4px;font-size:11px">Celular</span>':'<span style="background:rgba(59,130,246,.15);color:#3b82f6;padding:2px 8px;border-radius:4px;font-size:11px">Notebook</span>';
    return '<tr style="border-bottom:1px solid var(--bd)"><td style="padding:8px">'+tipoBadge+'</td><td style="padding:8px;font-weight:600">'+s(l.funcionario||'-')+'</td><td style="padding:8px;font-size:12px">'+s(equip.trim()||'-')+'</td><td style="padding:8px;font-size:12px;font-family:JetBrains Mono,monospace">'+s(l.assinadoCPF||'-')+'</td><td style="padding:8px;font-size:11px">'+s(l.assinadoEm||'-')+'</td><td style="padding:8px;font-size:11px;color:var(--t3)">'+s(l.assinadoIP||'-')+'</td><td style="padding:8px;white-space:nowrap"><button class="btn btn-p btn-sm" onclick="downloadSignedTerm(\''+l.id+'\')" style="padding:4px 10px;font-size:11px">📥 Baixar PDF</button> <button class="btn btn-d btn-sm" onclick="deleteSignedTerm(\''+l.id+'\')" style="padding:4px 10px;font-size:11px">🗑️</button></td></tr>';
  }).join('')}
  _syncSignedLinksFromCloud();
}
var _signedSyncDone=false;
function _syncSignedLinksFromCloud(){
  if(_signedSyncDone)return;
  _signedSyncDone=true;
  setTimeout(function(){_signedSyncDone=false},5000);
  function _pullAndRender(){
    var _url='https://galvabras-gestao-default-rtdb.firebaseio.com/galvabras/data/signLinks.json';
    fetchFB(_url).then(function(r){return r.json()}).then(function(cloudLinks){
      if(!cloudLinks)return;
      var d2=getDB();
      if(!d2.signLinks)d2.signLinks=[];
      var cloudArr=Array.isArray(cloudLinks)?cloudLinks:Object.values(cloudLinks);
      var changed=false;
      cloudArr.forEach(function(cl){
        if(!cl||!cl.id)return;
        var exists=d2.signLinks.find(function(x){return x.id===cl.id});
        if(!exists){d2.signLinks.push(cl);changed=true}
        else if(cl.assinado&&!exists.assinado){Object.assign(exists,cl);changed=true}
      });
      if(changed){setDB(d2)}
      var tb=document.getElementById('signedTermsTable');
      if(tb){
        var links2=(d2.signLinks||[]).filter(function(x){return x.assinado}).slice().reverse();
        var badge2=document.getElementById('signedCountBadge');
        if(badge2)badge2.textContent=links2.length+' assinado(s)';
        if(links2.length>0){
          tb.innerHTML=links2.map(function(l){
            var tipo2=l.tipo==='celular'?'\u{1F4F1} Celular':'\u{1F4BB} Notebook';
            var equip2=l.tipo==='celular'?(l.fabricante||'')+' '+(l.modelo||''):(l.fabricante||'')+' '+(l.modelo||'');
            var tipoBadge2=l.tipo==='celular'?'<span style="background:rgba(232,97,26,.15);color:#E8611A;padding:2px 8px;border-radius:4px;font-size:11px">Celular</span>':'<span style="background:rgba(59,130,246,.15);color:#3b82f6;padding:2px 8px;border-radius:4px;font-size:11px">Notebook</span>';
            return '<tr style="border-bottom:1px solid var(--bd)"><td style="padding:8px">'+tipoBadge2+'</td><td style="padding:8px;font-weight:600">'+s(l.funcionario||'-')+'</td><td style="padding:8px;font-size:12px">'+s(equip2.trim()||'-')+'</td><td style="padding:8px;font-size:12px;font-family:JetBrains Mono,monospace">'+s(l.assinadoCPF||'-')+'</td><td style="padding:8px;font-size:11px">'+s(l.assinadoEm||'-')+'</td><td style="padding:8px;font-size:11px;color:var(--t3)">'+s(l.assinadoIP||'-')+'</td><td style="padding:8px;white-space:nowrap"><button class="btn btn-p btn-sm" onclick="downloadSignedTerm(\''+l.id+'\')" style="padding:4px 10px;font-size:11px">\u{1F4E5} Baixar PDF</button> <button class="btn btn-d btn-sm" onclick="deleteSignedTerm(\''+l.id+'\')" style="padding:4px 10px;font-size:11px">\u{1F5D1}\uFE0F</button></td></tr>';
          }).join('');
        }
      }
    }).catch(function(e){console.warn('[Sign] REST pull error:',e)});
  }
/* Os links de assinatura sao lidos pelo proxy (fetchFB acima).
O SDK do Firebase nao e mais carregado - nao ha mais nada a
autenticar no lado do cliente. */
_pullAndRender();
}
function _pullSignLinksREST(){
  try{
    var _url='https://galvabras-gestao-default-rtdb.firebaseio.com/galvabras/data/signLinks.json';
    fetchFB(_url).then(function(r){return r.json()}).then(function(cloudLinks){
      if(!cloudLinks)return;
      var d2=getDB();
      if(!d2.signLinks)d2.signLinks=[];
      var cloudArr=Array.isArray(cloudLinks)?cloudLinks:Object.values(cloudLinks);
      var changed=false;
      cloudArr.forEach(function(cl){
        if(!cl||!cl.id)return;
        var exists=d2.signLinks.find(function(x){return x.id===cl.id});
        if(!exists){d2.signLinks.push(cl);changed=true}
        else if(cl.assinado&&!exists.assinado){Object.assign(exists,cl);changed=true}
      });
      if(changed){setDB(d2)}
    }).catch(function(e){console.warn('[Sign] REST pull error:',e)});
  }catch(e){}
}

function downloadSignedTerm(signId){
  var d=getDB();
  var link=(d.signLinks||[]).find(function(x){return x.id===signId});
  if(!link){toast('Termo não encontrado','e');return}
  try{generateSignedPDF(link);toast('PDF gerado!','s')}
  catch(e){console.error('PDF error:',e);toast('Erro ao gerar PDF: '+e.message,'e')}
}

function deleteSignedTerm(signId){
  if(!confirm('Excluir este termo assinado?'))return;
  var raw=JSON.parse(localStorage.getItem(DB)||'{}');
  raw.signLinks=(raw.signLinks||[]).filter(function(x){return x&&x.id!==signId});
  if(!raw.deletedIds)raw.deletedIds=[];
  var key='signLinks:'+String(signId);
  if(!raw.deletedIds.includes(key))raw.deletedIds.push(key);
  if(raw.deletedIds.length>500)raw.deletedIds=raw.deletedIds.slice(-500);
  localStorage.setItem(DB,JSON.stringify(raw));
  fetchFB('https://galvabras-gestao-default-rtdb.firebaseio.com/galvabras/data/signLinks/'+signId+'.json',{method:'DELETE'}).then(function(){
    renderSignedTerms();toast('Termo excluído!','s');
  }).catch(function(e){
    console.warn('Delete signed term failed, trying array approach:',e);
    fetchFB('https://galvabras-gestao-default-rtdb.firebaseio.com/galvabras/data/signLinks.json').then(function(r){return r.json()}).then(function(fbRaw){
      if(!fbRaw){renderSignedTerms();toast('Termo excluído!','s');return}
      var arr=Array.isArray(fbRaw)?fbRaw:Object.values(fbRaw);
      arr=arr.filter(function(x){return x&&x.id!==signId});
      var clean={};
      arr.forEach(function(x,i){clean[i]=x});
      return fetchFB('https://galvabras-gestao-default-rtdb.firebaseio.com/galvabras/data/signLinks.json',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(clean)});
    }).then(function(){renderSignedTerms();toast('Termo excluído!','s')}).catch(function(){renderSignedTerms();toast('Termo excluído!','s')});
  });
}

