function licOperPrintDo(id,token){
  const l=(getDB().licOper||[]).find(x=>x.id===id);
  if(!l){toast('Licença não encontrada.','e');return}
  const now=new Date().toLocaleString('pt-BR');
  const i=licOperStatusInfo(l);
  const dd=licOperDays(l);
  const diasTxt=dd===null?'':(dd<0?' (vencida há '+Math.abs(dd)+' dia(s))':(dd<=30?' (vence em '+dd+' dia(s))':''));
  const row=function(lb,vl){return '<div class="row"><div class="lb">'+lb+'</div><div class="vl">'+vl+'</div></div>'};
  const body='<div class="hd"><h1>LICENÇA OPERACIONAL - GRUPO GALVA</h1><p>'+s(l.empresa)+' — '+s(l.tipo)+'</p><p>Emissão da ficha: '+now+'</p></div>'
   +'<div class="box"><h3>DADOS DA LICENÇA</h3>'
   +row('Empresa:',s(l.empresa))
   +row('Tipo:',s(l.tipo))
   +row('Número / Processo:',s(l.numero||'-'))
   +row('Emissão:',licOperFmtDate(l.emissao))
   +row('Validade:',licOperFmtDate(l.validade)+diasTxt)
   +row('Status:',i.label)
   +row('Observações:',s(l.obs||'-'))
   +row('Anexo PDF:',l.arquivo?'Sim':'Não')
   +row('Cadastrado por:',s(l.criadoPor||'-'))
   +'</div>'
   +'<div class="box"><h3>VALIDADE</h3><div style="font-size:12px;color:#444">Situação calculada pela data de validade informada. Documento com anexo PDF disponível no sistema.</div></div>'
   +'<div class="sigsec"><div class="sig"><div class="sigline empty">____________________________</div><div class="lin">Responsável pelo setor</div></div><div class="sig"><div class="sigline empty">____________________________</div><div class="lin">Conferência / Validado por</div></div></div>'
   +'<div class="foot">Documento gerado pelo Sistema GALVABRAS em '+now+'</div>';
  segOpenPrint('Licença '+l.empresa+' - '+l.tipo,body);
  licOperRegPrint('Ficha individual','Ficha de licença: '+l.empresa+' / '+l.tipo,token||'sem token');
}

function licOperRegPrint(escopo,detail,token){
  try{
    const d=getDB();
    if(!d.licOperPrints)d.licOperPrints=[];
    d.licOperPrints.unshift({
      id:Date.now()+Math.floor(Math.random()*1000),
      data:new Date().toLocaleString('pt-BR'),
      user:user?user.nome:'Sistema',
      email:user?user.email:'-',
      perfil:user?profileName(user.profile):'-',
      token:token||'sem token',
      escopo:escopo||'',
      detail:detail||''
    });
    if(d.licOperPrints.length>50)d.licOperPrints=d.licOperPrints.slice(0,50);
    setDB(d);
    pushToFirebase();
  }catch(e){console.warn('licOperRegPrint',e)}
  addLog('print',detail||('Impressão de licenças: '+escopo));
}

function licOperPrintAll(token){
  if(!canAccessLicOper()){toast('Sem permissão para Licenças Operacionais','e');return}
  if(!window.jspdf||!window.jspdf.jsPDF){toast('Biblioteca de PDF indisponível.','e');return}
  const d=getDB();
  const list=(d.licOper)||[];
  if(!list.length){toast('Nenhuma licença cadastrada.','e');return}
  const jsPDF=window.jspdf.jsPDF;
  const doc=new jsPDF({unit:'mm',format:'a4'});
  const lm=14,W=210;
  const now=new Date();
  const infos=list.map(x=>({x:x,i:licOperStatusInfo(x)}));
  const venc=infos.filter(o=>o.i.k==='vencido');
  const aven=infos.filter(o=>o.i.k==='a-vencer');
  const val=infos.filter(o=>o.i.k==='valido');
  let y=0;

  doc.setFillColor(232,97,26);doc.rect(0,0,W,32,'F');ggLogo(doc,84,7,14);
  doc.setFont('helvetica','bold');doc.setFontSize(20);doc.setTextColor(255,255,255);
  doc.text('GALVABRAS',lm,15);
  doc.setFont('helvetica','normal');doc.setFontSize(9);
  doc.text('GRUPO GALVA - Licencas Operacionais',lm,22);
  doc.setFont('helvetica','bold');doc.setFontSize(13);
  doc.text('RELATORIO DE LICENCAS',W-lm,14,{align:'right'});
  doc.setFont('helvetica','normal');doc.setFontSize(9);
  doc.text('Emissao: '+now.toLocaleString('pt-BR'),W-lm,21,{align:'right'});
  doc.text('Total: '+list.length+' licenca(s)',W-lm,27,{align:'right'});

  y=42;
  const kpis=[['TOTAL',list.length,[63,130,246]],['VALIDAS',val.length,[16,185,129]],['A VENCER (30d)',aven.length,[245,158,11]],['VENCIDAS',venc.length,[239,68,68]]];
  const bw=(W-2*lm-12)/4;
  kpis.forEach((k,idx)=>{
    const x=lm+idx*(bw+4);
    doc.setDrawColor(215);doc.setLineWidth(0.3);doc.roundedRect(x,y,bw,16,2,2);
    doc.setFont('helvetica','normal');doc.setFontSize(7);doc.setTextColor(120);
    doc.text(k[0],x+bw/2,y+6,{align:'center'});
    doc.setFont('helvetica','bold');doc.setFontSize(14);doc.setTextColor(k[2][0],k[2][1],k[2][2]);
    doc.text(String(k[1]),x+bw/2,y+13,{align:'center'});
  });
  y+=24;

  function secTitle(txt){
    doc.setFont('helvetica','bold');doc.setFontSize(10);doc.setTextColor(40);
    doc.text(txt,lm,y);y+=3;
  }

  const comData=infos.filter(o=>o.x.validade).sort((a,b)=>String(a.x.validade).localeCompare(String(b.x.validade)));
  if(comData.length){
    secTitle('VENCIMENTOS (ordem cronologica)');
    doc.autoTable({
      startY:y,
      head:[['Empresa','Tipo de Licenca','Validade','Situacao','Dias']],
      body:comData.map(o=>{
        const dd=licOperDays(o.x);
        const dias=dd===null?'-':(dd<0?'vencida ha '+Math.abs(dd):(dd<=30?'vence em '+dd:String(dd)));
        return [o.x.empresa,o.x.tipo,licOperFmtDate(o.x.validade),o.i.label,dias];
      }),
      theme:'grid',
      styles:{fontSize:7,cellPadding:2.5,textColor:[40,40,40]},
      headStyles:{fillColor:[232,97,26],textColor:[255,255,255],fontStyle:'bold'},
      alternateRowStyles:{fillColor:[245,247,250]},
      columnStyles:{0:{cellWidth:44},1:{cellWidth:46},2:{cellWidth:32},3:{cellWidth:32},4:{cellWidth:28}},
      margin:{left:lm,right:lm},
      didParseCell:function(data){
        if(data.section==='body'&&data.column.index===3){
          const v=String(data.cell.raw);
          if(v==='Vencida')data.cell.styles.textColor=[200,30,30];
          else if(v==='A vencer')data.cell.styles.textColor=[190,120,0];
        }
      }
    });
    y=doc.lastAutoTable.finalY+8;
  }

  if(y>235){doc.addPage();y=20}
  secTitle('TODAS AS LICENCAS');
  doc.autoTable({
    startY:y,
    head:[['Empresa','Tipo','Numero','Emissao','Validade','Situacao','Anexo']],
    body:infos.map(o=>[o.x.empresa,o.x.tipo,o.x.numero||'-',licOperFmtDate(o.x.emissao),licOperFmtDate(o.x.validade),o.i.label,o.x.arquivo?'SIM':'nao']),
    theme:'grid',
    styles:{fontSize:7,cellPadding:2.5,textColor:[40,40,40]},
    headStyles:{fillColor:[232,97,26],textColor:[255,255,255],fontStyle:'bold'},
    alternateRowStyles:{fillColor:[245,247,250]},
    columnStyles:{0:{cellWidth:32},1:{cellWidth:38},2:{cellWidth:26},3:{cellWidth:24},4:{cellWidth:24},5:{cellWidth:24},6:{cellWidth:14}},
    margin:{left:lm,right:lm},
    didParseCell:function(data){
      if(data.section==='body'&&data.column.index===5){
        const v=String(data.cell.raw);
        if(v==='Vencida')data.cell.styles.textColor=[200,30,30];
        else if(v==='A vencer')data.cell.styles.textColor=[190,120,0];
      }
    }
  });
  y=doc.lastAutoTable.finalY+10;

  if(y>245){doc.addPage();y=20}
  doc.setDrawColor(200);doc.setLineWidth(0.3);doc.line(lm,y,W-lm,y);y+=6;
  doc.setFont('helvetica','bold');doc.setFontSize(9);doc.setTextColor(40);
  doc.text('IMPRESSAO CONTROLADA - TOKEN DA T.I.',lm,y);y+=5;
  doc.setFont('helvetica','normal');doc.setFontSize(8);doc.setTextColor(70);
  const linhas=[
    'Impresso por: '+(user?user.nome:'Sistema')+' ('+(user?user.email:'-')+')',
    'Perfil: '+(user?profileName(user.profile):'-')+'   |   Setor: '+(user?(user.dept||'-'):'-'),
    'Token T.I. utilizado: '+(token||'sem token'),
    'Data/Hora: '+now.toLocaleString('pt-BR'),
    'Totais: '+list.length+' licenca(s) | '+val.length+' valida(s) | '+aven.length+' a vencer | '+venc.length+' vencida(s)'
  ];
  linhas.forEach(function(t){doc.text(t,lm,y);y+=4.5});
  doc.setFontSize(7);doc.setTextColor(150);
  doc.text('Relatorio gerado pelo Sistema GALVABRAS - Area Licencas Operacionais',lm,y+3);

  const fname='Licencas_Operacionais_Grupo_Galva_'+now.toISOString().slice(0,10)+'.pdf';
  doc.save(fname);
  licOperRegPrint('PDF consolidado','PDF de todas as licencas ('+list.length+') gerado',token||'sem token');
  renderLicOper();
  toast('PDF gerado! Verifique seus downloads.','s');
}
